/* ===== utils/identity.js ===== */
/**
 * Optional local identity discriminator.
 * Raw CCCD / phone values are never persisted by this module.
 * They are only transformed into a short local fingerprint so two records
 * with identical name + birth data can still be distinguished when needed.
 */
const Identity={
  digits(v){return String(v||'').replace(/\D/g,'')},
  sourceLabel(cccd,phone){const c=!!this.digits(cccd),p=!!this.digits(phone);return c&&p?'CCCD + số điện thoại':c?'CCCD':p?'Số điện thoại':''},
  fallbackHash(text){
    let h1=0x811c9dc5,h2=0x9e3779b9;
    for(let i=0;i<text.length;i++){
      const c=text.charCodeAt(i);h1^=c;h1=Math.imul(h1,0x01000193);h2^=(c+i);h2=Math.imul(h2,0x85ebca6b);
    }
    return `${(h1>>>0).toString(16).padStart(8,'0')}${(h2>>>0).toString(16).padStart(8,'0')}`;
  },
  async fingerprint({cccd='',phone='',fullName='',birthDate=''}){
    const c=this.digits(cccd),p=this.digits(phone);if(!c&&!p)return '';
    const payload=`huyen-cac|${c}|${p}|${String(fullName).trim().toLowerCase()}|${birthDate}`;
    try{
      if(globalThis.crypto?.subtle&&globalThis.TextEncoder){
        const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(payload));
        return [...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('').slice(0,20);
      }
    }catch{}
    return this.fallbackHash(payload);
  }
};


/* ===== models/storage-model.js ===== */

class StorageModel{
  static memory=null;

  static load(){
    try{
      const raw=localStorage.getItem(MysticalData.STORE);
      return raw?JSON.parse(raw):this.memory;
    }catch{
      return this.memory;
    }
  }

  static save(profile){
    this.memory=profile;
    try{localStorage.setItem(MysticalData.STORE,JSON.stringify(profile))}catch{}
    return profile;
  }

  static clear(){
    this.memory=null;
    try{localStorage.removeItem(MysticalData.STORE)}catch{}
  }
}


/* ===== state/app-state.js ===== */

const AppState={
  value:{view:'home',profile:StorageModel.load(),tarot:null,compatibility:null,dates:null,showAllDates:false},
  listeners:new Set(),
  get(){return this.value},
  patch(patch){
    const changed={};
    for(const [key,value] of Object.entries(patch)){
      if(this.value[key]!==value) changed[key]=value;
    }
    if(!Object.keys(changed).length) return;
    this.value={...this.value,...changed};
    this.listeners.forEach(fn=>fn(this.value,changed));
  },
  subscribe(fn){this.listeners.add(fn);return()=>this.listeners.delete(fn)}
};

/* =========================================================
   FEATURE CONFIG — function-driven view metadata
   ========================================================= */


/* ===== models/numerology-calculator.js ===== */

/** Pure numerology model. No DOM access. */
class NumerologyCalculator{
  static stripName(s){return (s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/gi,'d').toUpperCase().replace(/[^A-Z]/g,'')}
  static reduce(n,masters=true){n=Math.abs(Number(n)||0);while(n>9&&!(masters&&[11,22,33].includes(n)))n=String(n).split('').reduce((a,b)=>a+Number(b),0);return n}
  static sumDigits(s){return String(s).replace(/\D/g,'').split('').reduce((a,b)=>a+Number(b),0)}
  static letterValue(ch){const i='ABCDEFGHIJKLMNOPQRSTUVWXYZ'.indexOf(ch);return i<0?0:(i%9)+1}
  static lifePath(ds){return this.reduce(this.sumDigits(ds),true)}
  static birthday(ds){return this.reduce(Number(ds.split('-')[2]),true)}
  static expression(name){return this.reduce([...this.stripName(name)].reduce((s,c)=>s+this.letterValue(c),0),true)}
  static soul(name){return this.reduce([...this.stripName(name)].filter(c=>'AEIOUY'.includes(c)).reduce((s,c)=>s+this.letterValue(c),0),true)}
  static personality(name){return this.reduce([...this.stripName(name)].filter(c=>!'AEIOUY'.includes(c)).reduce((s,c)=>s+this.letterValue(c),0),true)}
  static attitude(ds){const [,m,d]=ds.split('-').map(Number);return this.reduce(m+d,true)}
  static maturity(name,ds){return this.reduce(this.lifePath(ds)+this.expression(name),true)}
  static personalYear(ds,year=new Date().getFullYear()){const [,m,d]=ds.split('-').map(Number);return this.reduce(m+d+this.sumDigits(year),false)}
  static personalMonth(ds,date=new Date()){return this.reduce(this.personalYear(ds,date.getFullYear())+date.getMonth()+1,false)}
  static personalDay(ds,date=new Date()){return this.reduce(this.personalMonth(ds,date)+date.getDate(),false)}
  static info(n){return MysticalData.NUM_TEXT[n]||[`Số ${n}`,'một chỉ số bổ sung trong hồ sơ','đối chiếu với các chỉ số khác thay vì đọc riêng lẻ']}
  static baseNumber(n){return this.reduce(n,false)}

  static alignment(a,b){
    const x=this.baseNumber(a),y=this.baseNumber(b),distance=Math.abs(x-y),score=Math.max(18,Math.round(100-distance*11));
    const state=score>=88?'Giao thoa mạnh':score>=66?'Bổ trợ':score>=44?'Khác nhịp':'Độ tương phản cao';
    return {a,b,baseA:x,baseB:y,distance,score,state};
  }

  static family(n){
    if(n===11)return 'Trực giác';if(n===22)return 'Kiến tạo';if(n===33)return 'Phụng sự';
    const b=this.baseNumber(n);if([1,8].includes(b))return 'Chủ động';if([2,6].includes(b))return 'Kết nối';if([3,5].includes(b))return 'Biểu đạt';if(b===4)return 'Cấu trúc';if(b===7)return 'Chiêm nghiệm';return 'Nhân văn';
  }

  static alignmentNarrative(label,a,b){
    const x=this.alignment(a,b);
    let interpretation='';
    if(x.score>=88)interpretation='hai trục gần nhau, nên nhu cầu bên trong và cách vận hành có xu hướng dễ phối hợp; rủi ro là quá tin vào một cách làm quen thuộc.';
    else if(x.score>=66)interpretation='hai trục có nền chung nhưng vẫn tạo khác biệt đủ để bổ trợ; hiệu quả nhất khi bạn chủ động phân vai thay vì để chúng cạnh tranh.';
    else if(x.score>=44)interpretation='hai trục khá khác nhịp; đây không nhất thiết là mâu thuẫn, nhưng thường đòi hỏi bạn chuyển chế độ tùy bối cảnh.';
    else interpretation='độ tương phản cao; nếu thiếu tự quan sát, bạn có thể cảm thấy mình muốn một đằng nhưng lại biểu hiện hoặc hành động theo một hướng khác.';
    return {label,...x,interpretation};
  }

  static synthesis(values){
    const lifeExpression=this.alignment(values.life,values.expression),innerOuter=this.alignment(values.soul,values.personality),currentCycle=this.alignment(values.life,values.personalYear);
    const core=[values.life,values.expression,values.soul,values.personality,values.birthday,values.attitude,values.maturity];
    const familyCounts=core.reduce((acc,n)=>{const f=this.family(n);acc[f]=(acc[f]||0)+1;return acc},{});
    const dominant=Object.entries(familyCounts).sort((a,b)=>b[1]-a[1])[0]||['—',0];
    const axes=[
      {label:'Chủ đạo ↔ Biểu đạt',...lifeExpression,detail:`So sánh hướng vận hành từ ngày sinh (${values.life}) với cách năng lực được biểu đạt qua họ tên (${values.expression}).`},
      {label:'Linh hồn ↔ Nhân cách',...innerOuter,detail:`So sánh động lực bên trong (${values.soul}) với lớp biểu hiện người khác dễ nhận thấy (${values.personality}).`},
      {label:'Chủ đạo ↔ Năm cá nhân',...currentCycle,detail:`So sánh trục dài hạn (${values.life}) với nhịp của năm hiện tại (${values.personalYear}).`}
    ];
    const insights=[
      {label:'CỤM NỔI BẬT',value:dominant[0],detail:`${dominant[1]}/${core.length} chỉ số lõi nằm trong nhóm quy ước “${dominant[0]}”. Mẫu lặp này hữu ích để tìm chủ đề chung, nhưng không phải phép đo khoa học.`},
      {label:'TRONG ↔ NGOÀI',value:innerOuter.state,detail:`Linh hồn ${values.soul} và Nhân cách ${values.personality} có mức giao thoa nội bộ ${innerOuter.score}/100. Điểm này chỉ biểu diễn khoảng cách số học sau rút gọn.`},
      {label:'NHỊP HIỆN TẠI',value:currentCycle.state,detail:`Năm cá nhân ${values.personalYear} ${currentCycle.score>=66?'khá gần':'khá khác'} với trục Chủ đạo ${values.life}; nên đọc như gợi ý về nhịp ưu tiên, không phải dự báo.`}
    ];
    return {axes,insights,familyCounts,dominantFamily:dominant[0],dominantCount:dominant[1]};
  }



  static ageOn(ds,date=new Date()){
    const [y,m,d]=ds.split('-').map(Number);let age=date.getFullYear()-y;
    const before=date.getMonth()+1<m||(date.getMonth()+1===m&&date.getDate()<d);if(before)age--;
    return Math.max(0,age);
  }

  static ageStage(age){
    if(age<18)return {key:'learning',label:'Giai đoạn xây nền',range:'Dưới 18',focus:'học kỹ năng, tạo thói quen và hiểu giá trị của tiền/cảm xúc trước khi gánh quyết định dài hạn'};
    if(age<=24)return {key:'explore',label:'Giai đoạn thử nghiệm có kiểm soát',range:'18–24',focus:'tích lũy kỹ năng, trải nghiệm có giới hạn và xây nền tự lập'};
    if(age<=34)return {key:'build',label:'Giai đoạn xây nền dài hạn',range:'25–34',focus:'ổn định năng lực kiếm sống, chọn hướng dài hạn và xây các cam kết có chất lượng'};
    if(age<=44)return {key:'expand',label:'Giai đoạn mở rộng & tái cân bằng',range:'35–44',focus:'cân bằng tăng trưởng với sức bền, gia đình, trách nhiệm và chất lượng lựa chọn'};
    if(age<=54)return {key:'optimize',label:'Giai đoạn tối ưu & củng cố',range:'45–54',focus:'lọc bớt thứ kém hiệu quả, bảo toàn thành quả và ưu tiên chiều sâu hơn số lượng'};
    return {key:'preserve',label:'Giai đoạn bảo toàn & truyền lại giá trị',range:'55+',focus:'duy trì sự chủ động, bảo toàn nguồn lực và dành năng lượng cho điều có ý nghĩa lâu dài'};
  }

  static financeGuidance(values,age,now=new Date()){
    const family=this.family(values.life),exprFamily=this.family(values.expression),py=values.personalYear,stage=this.ageStage(age);
    const patterns={
      'Chủ động':{strength:'khả năng quyết nhanh, nhìn nguồn lực theo mục tiêu và chủ động tạo cơ hội',risk:'dễ quá tự tin, tập trung quá nhiều vào một lựa chọn hoặc quyết định nhanh khi chưa đủ dữ kiện'},
      'Kết nối':{strength:'khả năng thương lượng, duy trì quan hệ và tạo giá trị qua hợp tác',risk:'dễ chi tiêu theo cảm xúc, khó nói “không” hoặc nhường quá nhiều trong chuyện tiền bạc'},
      'Biểu đạt':{strength:'khả năng tìm cơ hội qua giao tiếp, sáng tạo và thích nghi nhanh',risk:'dễ phân tán nguồn thu, mua theo hứng hoặc chạy theo cơ hội mới trước khi tối ưu cái đang có'},
      'Cấu trúc':{strength:'khả năng lập kế hoạch, giữ kỷ luật và xây nền tài chính đều đặn',risk:'dễ quá thận trọng, bỏ lỡ cơ hội hợp lý hoặc giữ một mô hình cũ quá lâu chỉ vì nó quen thuộc'},
      'Chiêm nghiệm':{strength:'khả năng nghiên cứu, soi rủi ro và không dễ bị cuốn theo đám đông',risk:'dễ chậm quyết định vì muốn đủ chắc chắn hoặc bỏ qua cơ hội vì phân tích quá lâu'},
      'Nhân văn':{strength:'khả năng nhìn tiền như công cụ phục vụ giá trị lớn hơn và tạo tác động',risk:'dễ cho đi quá tay, định giá thấp công sức hoặc đặt lý tưởng cao hơn giới hạn nguồn lực'},
      'Trực giác':{strength:'khả năng nhận ra mô-típ, xu hướng và cơ hội khác thường',risk:'dễ đánh đồng trực giác với bằng chứng, đặc biệt khi quyết định có yếu tố đầu cơ'},
      'Kiến tạo':{strength:'khả năng nghĩ dài hạn, xây hệ thống và biến mục tiêu lớn thành cấu trúc',risk:'dễ mở rộng quá nhanh, ôm dự án lớn hoặc dùng đòn bẩy trước khi nền dòng tiền đủ chắc'},
      'Phụng sự':{strength:'khả năng tạo giá trị bền nhờ trách nhiệm, chất lượng dịch vụ và uy tín',risk:'dễ làm nhiều hơn mức được trả hoặc đặt nhu cầu người khác lên trên an toàn tài chính của mình'}
    };
    const p=patterns[family]||patterns['Biểu đạt'];
    const ageAdvice={
      learning:['Tập thói quen ghi chép tiền vào/ra và hiểu khác biệt giữa nhu cầu với ham muốn.','Không vay/nợ hoặc mua sắm theo áp lực bạn bè; ưu tiên học kỹ năng trước khi tìm “cách kiếm tiền nhanh”.'],
      explore:['Xây quỹ dự phòng nhỏ, đầu tư vào kỹ năng tạo thu nhập và tập đều một thói quen tiết kiệm.','Tránh nợ tiêu dùng, đầu cơ theo FOMO và dồn phần lớn tiền vào một cơ hội chưa hiểu rõ.'],
      build:['Ưu tiên quỹ dự phòng, bảo hiểm phù hợp, tăng năng lực kiếm tiền và tích lũy đều theo kế hoạch.','Tránh nâng mức sống nhanh hơn thu nhập bền vững hoặc gánh khoản vay dài hạn chỉ vì áp lực so sánh.'],
      expand:['Đa dạng hóa nguồn lực, rà soát rủi ro gia đình/công việc và dành tỷ lệ rõ cho mục tiêu dài hạn.','Tránh dùng đòn bẩy quá mức, mở rộng nhiều dự án cùng lúc hoặc xem thu nhập hiện tại là chắc chắn vĩnh viễn.'],
      optimize:['Củng cố tài sản, giảm khoản kém hiệu quả, kiểm tra kế hoạch nghỉ hưu và tính thanh khoản.','Tránh giữ khoản đầu tư chỉ vì “đã bỏ nhiều tiền” hoặc chấp nhận rủi ro cao để bù cho thời gian đã qua.'],
      preserve:['Ưu tiên bảo toàn vốn, thanh khoản, chống gian lận và kế hoạch chuyển giao/tài sản rõ ràng.','Tránh sản phẩm phức tạp không hiểu rõ, cam kết lợi nhuận cao và quyết định tài chính do người khác gây áp lực.']
    }[stage.key];
    const cycleTip={1:'Năm 1 hợp để rà soát cấu trúc thu nhập và bắt đầu một thói quen tài chính mới ở quy mô nhỏ.',2:'Năm 2 nhấn mạnh hợp tác: tiền bạc nên có quy ước rõ khi liên quan người khác.',3:'Năm 3 dễ có nhiều ý tưởng và chi tiêu trải nghiệm; cần một ngân sách vui chơi rõ ràng.',4:'Năm 4 hợp với kỷ luật, trả nợ, tích lũy và tối ưu quy trình tài chính.',5:'Năm 5 dễ có biến động/thử nghiệm; nên tăng quỹ đệm trước khi mở rộng rủi ro.',6:'Năm 6 thường kéo trách nhiệm gia đình/cam kết lên cao; nên phân biệt hỗ trợ hợp lý và gánh thay.',7:'Năm 7 hợp với rà soát, học sâu và tránh quyết định đầu tư vì sốt ruột.',8:'Năm 8 phù hợp đặt mục tiêu tài chính đo được, nhưng càng cần kỷ luật rủi ro và minh bạch số liệu.',9:'Năm 9 hợp để dọn khoản kém hiệu quả, khép nghĩa vụ cũ và tránh mở cam kết dài hạn chỉ vì cảm xúc.'}[py];
    return {title:`Tài chính ở tuổi ${age}`,stage,profile:`Trục ${values.life} (${family}) kết hợp Biểu đạt ${values.expression} (${exprFamily}) cho thấy bạn có thể phát huy tốt ở ${p.strength}.`,risk:p.risk,doNow:ageAdvice[0],avoid:ageAdvice[1],cycleTip,disclaimer:'Đây là góc nhìn hành vi và quản trị rủi ro, không phải dự báo giàu/nghèo hay khuyến nghị đầu tư cá nhân.'};
  }

  static futureGuidance(values,age,now=new Date()){
    const stage=this.ageStage(age),py=values.personalYear,life=this.info(values.life),maturity=this.info(values.maturity);
    const cycle={
      1:{do:'chọn một hướng mới đủ nhỏ để bắt đầu ngay và đặt mốc kiểm tra sau 30–90 ngày',avoid:'mở quá nhiều dự án cùng lúc hoặc đổi hướng chỉ vì cảm giác muốn làm mới'},
      2:{do:'đầu tư vào quan hệ, kỹ năng lắng nghe và những việc cần phối hợp bền bỉ',avoid:'ép tiến độ khi điều kiện chưa chín hoặc im lặng quá lâu để giữ hòa khí'},
      3:{do:'đưa ý tưởng ra ngoài, thử sản phẩm/nội dung/kỹ năng giao tiếp và đo phản hồi thực tế',avoid:'chạy theo cảm hứng mà thiếu lịch hoàn thành'},
      4:{do:'xây quy trình, chuẩn hóa thói quen và hoàn thiện nền tảng đang còn lỏng',avoid:'cứng nhắc với kế hoạch khi dữ kiện thực tế đã thay đổi'},
      5:{do:'thử nghiệm có giới hạn, học kỹ năng mới và chủ động tạo phương án dự phòng',avoid:'đánh đồng thay đổi với tiến bộ hoặc bỏ cái đang tốt chỉ vì chán'},
      6:{do:'làm rõ cam kết, trách nhiệm và cân bằng giữa mình với gia đình/đội nhóm',avoid:'ôm trách nhiệm của người khác đến mức cạn năng lượng'},
      7:{do:'học sâu, rà soát hướng đi và dành thời gian cho công việc cần tập trung chất lượng cao',avoid:'cô lập hoặc trì hoãn vô hạn vì chưa cảm thấy “đủ chắc”'},
      8:{do:'đặt mục tiêu kết quả đo được, quản lý nguồn lực và học cách đàm phán giá trị của mình',avoid:'để áp lực thành tích khiến quyết định ngắn hạn lấn át rủi ro dài hạn'},
      9:{do:'hoàn tất việc dang dở, đóng vòng cũ và giải phóng nguồn lực cho chu kỳ kế tiếp',avoid:'níu giữ một hướng đã không còn hiệu quả chỉ vì tiếc công sức đã bỏ ra'}
    }[py];
    return {age,stage,headline:`${stage.label} • Năm cá nhân ${py}`,context:`Ở tuổi ${age}, ưu tiên phát triển hợp lý thường là ${stage.focus}. Trục Chủ đạo ${values.life} (${life[0]}) cho thấy cách bạn thường khởi động vấn đề, còn Số trưởng thành ${values.maturity} (${maturity[0]}) gợi hướng năng lực cần được tích hợp nhiều hơn khi tuổi và trách nhiệm tăng lên.`,should:cycle.do,avoid:cycle.avoid,checkpoint:`Trong 6–12 tháng tới, hãy chọn tối đa 2 mục tiêu có thể đo được. Mỗi quý tự hỏi: “việc này đang tạo năng lực/tài sản/quan hệ tốt hơn, hay chỉ đang làm tôi bận hơn?”`,disclaimer:'Phần “tương lai” không dự đoán sự kiện sẽ xảy ra. Nó chỉ chuyển độ tuổi + chu kỳ hiện tại thành các ưu tiên thực hành để bạn tự quyết định.'};
  }

  static loveGuidance(values,age,now=new Date()){
    const soul=this.info(values.soul),personality=this.info(values.personality),life=this.info(values.life),py=values.personalYear,stage=this.ageStage(age);
    const ageFocus=age<25?'ưu tiên hiểu ranh giới, nhịp riêng và kiểu quan tâm khiến bạn cảm thấy được tôn trọng':age<35?'ưu tiên phân biệt hấp dẫn ban đầu với sự tương thích về giá trị, trách nhiệm và kế hoạch sống':age<45?'ưu tiên khả năng cùng gánh trách nhiệm, sửa chữa sau xung đột và giữ không gian phát triển cá nhân':age<55?'ưu tiên chất lượng đồng hành, sự trung thực, tôn trọng nhịp sống và cách hai người chăm sóc mối quan hệ qua thời gian':'ưu tiên sự bình an, tin cậy, quyền tự chủ và khả năng đồng hành thực tế hơn là hình ảnh lý tưởng về một mối quan hệ';
    const cycleHint=[2,6].includes(py)?'Chu kỳ hiện tại đặt nhiều chú ý vào hợp tác/cam kết; đây là lúc phù hợp để nói rõ nhu cầu và kỳ vọng thay vì chỉ đoán ý nhau.':py===5?'Chu kỳ hiện tại có nhiều năng lượng thay đổi; nếu tình cảm biến động, cần phân biệt nhu cầu tự do lành mạnh với phản ứng bốc đồng.':py===7?'Chu kỳ hiện tại thiên về nhìn lại; khoảng riêng có thể hữu ích nếu được giao tiếp rõ, nhưng im lặng kéo dài dễ biến thành xa cách.':py===9?'Chu kỳ hiện tại hợp với việc khép những mô-típ cũ; thay vì cố giữ mọi thứ, hãy xem điều gì cần được sửa, tha thứ hoặc kết thúc có trách nhiệm.':'Chu kỳ hiện tại không phải “năm tình duyên” cố định; hãy dùng nó như nhịp nền để điều chỉnh cách giao tiếp và mức cam kết.';
    return {title:'Đường tình duyên & cách bạn gắn kết',need:`Linh hồn ${values.soul} (${soul[0]}) gợi nhu cầu bên trong nghiêng về ${soul[1]}. Trong tình cảm, điều quan trọng là biến nhu cầu này thành câu nói/hành vi cụ thể thay vì chờ người kia tự hiểu.`,outer:`Nhân cách ${values.personality} (${personality[0]}) là lớp người khác dễ nhìn thấy. Nếu lớp này khác với điều bạn cần bên trong, bạn có thể tạo cảm giác mạnh mẽ/bình thản hơn thực tế và khiến đối phương đọc sai tín hiệu.`,pattern:`Chủ đạo ${values.life} (${life[0]}) cho thấy mô-típ dài hạn của bạn là ${life[1]}. Ở tuổi ${age}, ${ageFocus}.`,cycleHint,greenFlags:['tôn trọng ranh giới và quyền nói “không”','nói được chuyện tiền bạc, gia đình, thời gian và cam kết mà không né tránh','sau xung đột có hành động sửa chữa chứ không chỉ xin lỗi bằng lời'],redFlags:['buộc bạn phải thu nhỏ bản thân để giữ quan hệ','kiểm soát, gây sợ hãi hoặc làm bạn mất quyền tự quyết','lời nói và hành vi liên tục không nhất quán trong thời gian dài'],disclaimer:'Không có con số nào xác định bạn “sẽ yêu ai” hay “khi nào kết hôn”. Chất lượng tình duyên phụ thuộc vào lựa chọn, kỹ năng giao tiếp, ranh giới, sự an toàn và cách hai người cùng trưởng thành.'};
  }

  static expertReading(values,now){
    const li=this.info(values.life),ei=this.info(values.expression),si=this.info(values.soul),pi=this.info(values.personality),mi=this.info(values.maturity);
    const le=this.alignment(values.life,values.expression),io=this.alignment(values.soul,values.personality),cycleRel=this.alignment(values.life,values.personalYear);
    const pm=this.personalMonthFromValues(values,now),pd=this.personalDayFromValues(values,now),dominant=this.synthesis(values).dominantFamily;
    const style=le.score>=80
      ?`Điều bạn muốn trở thành và cách bạn thường thể hiện ra ngoài khá cùng hướng. Khi đã tin vào một việc, bạn có xu hướng huy động năng lực tương đối liền mạch. Điểm cần để ý là đừng biến “đúng phong cách của mình” thành lý do để bỏ qua phản hồi.`
      :le.score>=58
      ?`Bên trong bạn có một hướng khá rõ, nhưng cách triển khai ra ngoài không phải lúc nào cũng đi cùng một nhịp. Đây thường là dạng hồ sơ có khả năng thích nghi tốt: cùng một mục tiêu nhưng có thể dùng nhiều cách tiếp cận. Khi mệt hoặc chịu áp lực, sự linh hoạt này dễ biến thành phân tán.`
      :`Giữa động lực cốt lõi và cách biểu đạt có độ tương phản đáng kể. Bạn có thể muốn một điều nhưng lại hành động theo cách khiến người khác hiểu thành một điều khác. Điểm mấu chốt không phải “sửa con số”, mà là học cách gọi tên nhu cầu trước khi phản ứng.`;
    const inner=io.score>=80
      ?`Điều bạn cần ở bên trong khá dễ đi ra thành cách cư xử mà người khác nhìn thấy. Ưu điểm là tính nhất quán; mặt trái là đôi khi bạn cho rằng người khác “phải tự hiểu” vì với bạn mọi thứ vốn đã rõ.`
      :io.score>=58
      ?`Bạn không phải lúc nào cũng biểu lộ đúng mức điều mình đang cần. Có lúc bạn rất hiểu cảm xúc hoặc mong muốn của mình, nhưng lớp bên ngoài lại chọn một cách nói an toàn hơn. Vì vậy giao tiếp rõ nhu cầu sẽ hữu ích hơn việc chờ người khác đoán.`
      :`Khoảng cách giữa đời sống bên trong và hình ảnh bên ngoài khá rõ trong mô hình này. Người khác có thể gặp một phiên bản rất khác với điều bạn thực sự đang trải qua. Nếu gần đây thường xuyên thấy “không ai hiểu mình”, hãy kiểm tra trước xem bạn đã nói đủ cụ thể hay chưa.`;
    const cycle=cycleRel.score>=70
      ?`Nhịp năm ${values.personalYear} đang khá thuận với cách bạn vốn vận hành. Đây là thời điểm hợp để làm sâu những gì đã chứng minh được hiệu quả, thay vì mở quá nhiều hướng chỉ vì cảm giác phải thay đổi.`
      :`Nhịp năm ${values.personalYear} đang yêu cầu một kiểu vận hành hơi khác thói quen dài hạn. Cảm giác “không đúng nhịp” không nhất thiết là dấu hiệu xấu; nó có thể là giai đoạn buộc bạn học thêm một năng lực mà bình thường ít dùng.`;
    const shadow=li[2];
    return `
      <div class="fortune-narrative">
        <section class="fortune-lead-story"><span class="expert-kicker">BỨC TRANH CHUNG</span><h4>${li[0]} — nhưng không chỉ có một con số</h4><p>Nếu đọc toàn hồ sơ như một câu chuyện, trục chính của bạn nghiêng về <strong>${li[1]}</strong>. Cụm chủ đề lặp lại nhiều nhất thuộc nhóm <strong>${dominant}</strong>, nên đây có thể là kiểu năng lượng bạn dùng khá tự nhiên trong công việc, quan hệ hoặc lúc ra quyết định. Tuy nhiên, điểm đáng giá nhất không nằm ở nhãn “số ${values.life}”, mà ở việc nhận ra <strong>khi nào thế mạnh này giúp bạn tiến lên và khi nào nó bị dùng quá mức</strong>.</p></section>
        <div class="fortune-story-grid">
          <section class="fortune-story-block"><span class="expert-kicker">KHI BẠN Ở TRẠNG THÁI TỐT</span><h4>Bạn phát huy mạnh khi có không gian dùng đúng cách của mình</h4><p>${style}</p></section>
          <section class="fortune-story-block"><span class="expert-kicker">BÊN TRONG & CÁCH NGƯỜI KHÁC THẤY</span><h4>Linh hồn ${values.soul} gặp Nhân cách ${values.personality}</h4><p>${inner}</p></section>
          <section class="fortune-story-block"><span class="expert-kicker">ĐIỂM DỄ MẮC KẸT</span><h4>Điểm mạnh khi dùng quá mức có thể trở thành áp lực</h4><p>Với trục ${values.life}, điều nên tự kiểm tra là: <strong>${shadow}</strong>. Khi căng thẳng, thay vì hỏi “mình có đúng với con số này không?”, hãy hỏi cụ thể hơn: <em>tôi đang né quyết định, ôm quá nhiều, kiểm soát quá chặt hay phân tán vì điều gì?</em> Một câu hỏi gắn với hành vi luôn hữu ích hơn một nhãn tính cách.</p></section>
          <section class="fortune-story-block"><span class="expert-kicker">GIAI ĐOẠN HIỆN TẠI</span><h4>Năm ${values.personalYear} → tháng ${pm} → ngày ${pd}</h4><p>${cycle} Chu kỳ tháng và ngày chỉ nên dùng để điều chỉnh <strong>cường độ và ưu tiên</strong>, không dùng để trì hoãn một việc cần làm hay phó mặc quyết định cho con số.</p></section>
        </div>
        <section class="fortune-practice"><span class="expert-kicker">THỬ TRONG 30 NGÀY</span><h4>Ba cách biến phần đọc thành dữ kiện thật</h4><ol><li>Ghi lại 2 tình huống bạn cảm thấy “rất là mình” và xem thế mạnh nào đang được sử dụng.</li><li>Ghi lại 1 tình huống khiến bạn mệt hoặc bị hiểu sai; đối chiếu xem vấn đề nằm ở nhu cầu bên trong hay cách biểu đạt ra ngoài.</li><li>Chọn một hành vi nhỏ phù hợp với giai đoạn hiện tại và đo bằng kết quả thực tế sau 2–4 tuần, thay vì dựa vào cảm giác “hợp số”.</li></ol><p class="fortune-disclaimer">Thần số học ở đây là một hệ quy chiếu phản tư. Nó không đo được toàn bộ tính cách, năng lực hay tương lai của một người. Bản thân bạn, trải nghiệm, môi trường và lựa chọn thực tế luôn có trọng lượng lớn hơn các phép tính này.</p></section>
      </div>`;
  }

  static personalMonthFromValues(values,date){return this.reduce(values.personalYear+date.getMonth()+1,false)}
  static personalDayFromValues(values,date){return this.reduce(this.personalMonthFromValues(values,date)+date.getDate(),false)}

  static genderInsight(g,lp,ex,so,pe){
    if(g==='male')return `<strong>Hồ sơ Nam:</strong> giới tính không làm thay đổi phép tính. Với Chủ đạo <strong>${lp}</strong> và Biểu đạt <strong>${ex}</strong>, hãy quan sát cách bạn dùng tính tự chủ, trách nhiệm và khả năng chia sẻ nhu cầu. Linh hồn <strong>${so}</strong> so với Nhân cách <strong>${pe}</strong> hữu ích để nhận ra khoảng cách giữa điều thực sự cần và hình ảnh bạn đang duy trì.`;
    if(g==='female')return `<strong>Hồ sơ Nữ:</strong> giới tính không làm thay đổi phép tính. Với Chủ đạo <strong>${lp}</strong> và Biểu đạt <strong>${ex}</strong>, hãy quan sát sự cân bằng giữa tự chủ, ranh giới và kỳ vọng bên ngoài. Linh hồn <strong>${so}</strong> và Nhân cách <strong>${pe}</strong> giúp soi rõ phần nhu cầu bên trong chưa được biểu đạt đủ.`;
    if(g==='other')return `<strong>Hồ sơ không dùng phân loại Nam/Nữ:</strong> các chỉ số vẫn được tính đầy đủ. Hãy đọc Chủ đạo <strong>${lp}</strong>, Biểu đạt <strong>${ex}</strong>, Linh hồn <strong>${so}</strong> và Nhân cách <strong>${pe}</strong> theo trải nghiệm cá nhân.`;
    return 'Bạn chưa chọn giới tính. Các phép tính vẫn hoạt động bình thường; chỉ lớp diễn giải theo Nam/Nữ được bỏ qua.';
  }

  static calculate(profile,now=new Date()){
    const ds=profile.birthDate,name=profile.fullName;
    const values={life:this.lifePath(ds),expression:this.expression(name),soul:this.soul(name),personality:this.personality(name),birthday:this.birthday(ds),attitude:this.attitude(ds),maturity:this.maturity(name,ds),personalYear:this.personalYear(ds,now.getFullYear())};
    const metrics=[
      {label:'SỐ CHỦ ĐẠO',value:values.life,title:this.info(values.life)[0],note:'Tổng chữ số ngày sinh'},
      {label:'SỐ BIỂU ĐẠT',value:values.expression,title:this.info(values.expression)[0],note:'Giá trị chữ cái họ tên'},
      {label:'SỐ LINH HỒN',value:values.soul,title:this.info(values.soul)[0],note:'Chỉ nguyên âm'},
      {label:'SỐ NHÂN CÁCH',value:values.personality,title:this.info(values.personality)[0],note:'Chỉ phụ âm'},
      {label:'SỐ NGÀY SINH',value:values.birthday,title:this.info(values.birthday)[0],note:'Rút gọn ngày sinh'},
      {label:'SỐ THÁI ĐỘ',value:values.attitude,title:this.info(values.attitude)[0],note:'Tháng sinh + ngày sinh'},
      {label:'SỐ TRƯỞNG THÀNH',value:values.maturity,title:this.info(values.maturity)[0],note:'Chủ đạo + Biểu đạt'},
      {label:'NĂM CÁ NHÂN',value:values.personalYear,title:`Chu kỳ ${values.personalYear}`,note:`Năm ${now.getFullYear()}`}
    ];
    const reading=this.expertReading(values,now);
    const pm=this.personalMonth(ds,now),pd=this.personalDay(ds,now);
    const cycles=[{value:values.personalYear,label:'Năm cá nhân',text:MysticalData.CYCLE_TEXT[values.personalYear],meta:String(now.getFullYear())},{value:pm,label:'Tháng cá nhân',text:MysticalData.CYCLE_TEXT[pm],meta:`Tháng ${now.getMonth()+1}`},{value:pd,label:'Ngày cá nhân',text:MysticalData.CYCLE_TEXT[pd],meta:Format.vn(now,{day:'2-digit',month:'2-digit'})}];
    const clean=this.stripName(name),vowels=[...clean].filter(c=>'AEIOUY'.includes(c)).join(''),cons=[...clean].filter(c=>!'AEIOUY'.includes(c)).join('');
    const formulas=[['Số chủ đạo',`digits(${ds}) → tổng ${this.sumDigits(ds)} → ${values.life}`],['Số biểu đạt',`${clean||'—'} → Pythagoras 1–9 → ${values.expression}`],['Số linh hồn',`${vowels||'—'} → nguyên âm → ${values.soul}`],['Số nhân cách',`${cons||'—'} → phụ âm → ${values.personality}`],['Số thái độ',`${Number(ds.split('-')[1])} + ${Number(ds.split('-')[2])} → ${values.attitude}`],['Số trưởng thành',`${values.life} + ${values.expression} → ${values.maturity}`]];
    const age=this.ageOn(ds,now),ageStage=this.ageStage(age),finance=this.financeGuidance(values,age,now),future=this.futureGuidance(values,age,now),love=this.loveGuidance(values,age,now);
    return {values,metrics,reading,cycles,formulas,synthesis:this.synthesis(values),genderReading:this.genderInsight(profile.gender,values.life,values.expression,values.soul,values.personality),age,ageStage,finance,future,love};
  }
}


/* ===== models/lunar-converter.js ===== */

class LunarConverter{
  static jdFromDate(dd,mm,yy){let a=Math.floor((14-mm)/12),y=yy+4800-a,m=mm+12*a-3;let jd=dd+Math.floor((153*m+2)/5)+365*y+Math.floor(y/4)-Math.floor(y/100)+Math.floor(y/400)-32045;if(jd<2299161)jd=dd+Math.floor((153*m+2)/5)+365*y+Math.floor(y/4)-32083;return jd}
  static newMoon(k){const T=k/1236.85,T2=T*T,T3=T2*T,dr=Math.PI/180;let Jd1=2415020.75933+29.53058868*k+0.0001178*T2-0.000000155*T3;Jd1+=0.00033*Math.sin((166.56+132.87*T-0.009173*T2)*dr);const M=359.2242+29.10535608*k-0.0000333*T2-0.00000347*T3;const Mpr=306.0253+385.81691806*k+0.0107306*T2+0.00001236*T3;const F=21.2964+390.67050646*k-0.0016528*T2-0.00000239*T3;let C1=(0.1734-0.000393*T)*Math.sin(M*dr)+0.0021*Math.sin(2*dr*M);C1=C1-0.4068*Math.sin(Mpr*dr)+0.0161*Math.sin(2*dr*Mpr);C1-=0.0004*Math.sin(3*dr*Mpr);C1+=0.0104*Math.sin(2*dr*F)-0.0051*Math.sin((M+Mpr)*dr)-0.0074*Math.sin((M-Mpr)*dr)+0.0004*Math.sin((2*F+M)*dr)-0.0004*Math.sin((2*F-M)*dr)-0.0006*Math.sin((2*F+Mpr)*dr)+0.0010*Math.sin((2*F-Mpr)*dr)+0.0005*Math.sin((2*Mpr+M)*dr);let dt;if(T<-11)dt=0.001+0.000839*T+0.0002261*T2-0.00000845*T3-0.000000081*T*T3;else dt=-0.000278+0.000265*T+0.000262*T2;return Jd1+C1-dt}
  static sunLongitude(jdn){const T=(jdn-2451545)/36525,T2=T*T,dr=Math.PI/180,M=357.52910+35999.05030*T-0.0001559*T2-0.00000048*T*T2,L0=280.46645+36000.76983*T+0.0003032*T2;let DL=(1.914600-0.004817*T-0.000014*T2)*Math.sin(dr*M);DL+=(0.019993-0.000101*T)*Math.sin(dr*2*M)+0.000290*Math.sin(dr*3*M);let L=(L0+DL)*dr;return L-Math.PI*2*Math.floor(L/(Math.PI*2))}
  static getNewMoonDay(k,tz=MysticalData.TZ){return Math.floor(this.newMoon(k)+0.5+tz/24)}
  static getSunLongitude(day,tz=MysticalData.TZ){return Math.floor(this.sunLongitude(day-0.5-tz/24)/Math.PI*6)}
  static month11(yy,tz=MysticalData.TZ){const off=this.jdFromDate(31,12,yy)-2415021,k=Math.floor(off/29.530588853),nm=this.getNewMoonDay(k,tz),sl=this.getSunLongitude(nm,tz);return sl>=9?this.getNewMoonDay(k-1,tz):nm}
  static leapOffset(a11,tz=MysticalData.TZ){const k=Math.floor(0.5+(a11-2415021.076998695)/29.530588853);let last=0,i=1,arc=this.getSunLongitude(this.getNewMoonDay(k+i,tz),tz);do{last=arc;i++;arc=this.getSunLongitude(this.getNewMoonDay(k+i,tz),tz)}while(arc!==last&&i<14);return i-1}
  static solarToLunar(dd,mm,yy,tz=MysticalData.TZ){const dayNumber=this.jdFromDate(dd,mm,yy),k=Math.floor((dayNumber-2415021.076998695)/29.530588853);let monthStart=this.getNewMoonDay(k+1,tz);if(monthStart>dayNumber)monthStart=this.getNewMoonDay(k,tz);let a11=this.month11(yy,tz),b11=a11,lunarYear;if(a11>=monthStart){lunarYear=yy;a11=this.month11(yy-1,tz)}else{lunarYear=yy+1;b11=this.month11(yy+1,tz)}const lunarDay=dayNumber-monthStart+1,diff=Math.floor((monthStart-a11)/29);let leap=0,lunarMonth=diff+11;if(b11-a11>365){const leapDiff=this.leapOffset(a11,tz);if(diff>=leapDiff){lunarMonth=diff+10;if(diff===leapDiff)leap=1}}if(lunarMonth>12)lunarMonth-=12;if(lunarMonth>=11&&diff<4)lunarYear-=1;return {day:lunarDay,month:lunarMonth,year:lunarYear,leap}}
  static fromDate(date){return this.solarToLunar(date.getDate(),date.getMonth()+1,date.getFullYear())}
}


/* ===== models/astrology-calculator.js ===== */

/** Pure Can Chi / horoscope model. No DOM access. */
class AstrologyCalculator{
  static yearCanChi(y){const si=(y+6)%10,bi=(y+8)%12;return this.pack(si,bi)}
  static dayCanChi(date){const jd=LunarConverter.jdFromDate(date.getDate(),date.getMonth()+1,date.getFullYear()),si=((jd+9)%10+10)%10,bi=((jd+1)%12+12)%12;return {...this.pack(si,bi),jd}}
  static hourBranchIndex(time){if(!time)return null;const [h,m]=time.split(':').map(Number),mins=h*60+m;if(mins>=1380||mins<60)return 0;return Math.floor((mins-60)/120)+1}
  static hourCanChi(date,time){const bi=this.hourBranchIndex(time);if(bi===null)return null;const day=this.dayCanChi(date),si=((day.stemIndex%5)*2+bi)%10;return this.pack(si,bi)}
  static pack(si,bi){return {stemIndex:si,branchIndex:bi,stem:MysticalData.STEMS[si],branch:MysticalData.BRANCHES[bi],animal:MysticalData.ANIMALS[bi],element:MysticalData.STEM_ELEMENT[si]}}
  static relations(bi){const tri=MysticalData.TRINES.find(x=>x.includes(bi))||[],cl=MysticalData.CLASH.find(x=>x.includes(bi))||[];return {trine:tri.filter(x=>x!==bi),clash:cl.find(x=>x!==bi)}}
  static trineInfo(i){return MysticalData.TRINE_DETAIL.find(x=>x.members.includes(i))}
  static fourClashInfo(i){return MysticalData.FOUR_CLASH.find(x=>x.members.includes(i))}
  static branchFull(i){return `${MysticalData.BRANCHES[i]} (${MysticalData.ANIMALS[i]} • ${MysticalData.BRANCH_ELEMENT[i]} • ${MysticalData.BRANCH_POLARITY[i]})`}
  static stemFull(i){return `${MysticalData.STEMS[i]} (${MysticalData.STEM_ELEMENT[i]} • ${MysticalData.STEM_POLARITY[i]})`}
  static relationBetween(a,b){if(b===null||b===undefined)return 'Chưa có dữ liệu';if(a===b)return `Đồng chi ${MysticalData.BRANCHES[a]}`;const r=this.relations(a);if(r.trine.includes(b))return `Tam hợp — cùng nhóm ${this.trineInfo(a).name}`;if(r.clash===b)return `Lục xung / đối xung trực tiếp — ${MysticalData.BRANCHES[a]} ↔ ${MysticalData.BRANCHES[b]}`;if(MysticalData.SIX_HARMONY[a]===b)return `Lục hợp — ${MysticalData.BRANCHES[a]} ↔ ${MysticalData.BRANCHES[b]}`;const f=this.fourClashInfo(a);if(f?.members.includes(b))return `Cùng nhóm Tứ hành xung ${f.name}, nhưng không phải cặp đối xung trực tiếp`;return `Không thuộc Tam hợp, Lục hợp hoặc cặp đối xung trực tiếp`}
  static relationDescriptor(a,b){
    if(b===null||b===undefined)return {type:'missing',tone:'neutral',label:'Chưa có dữ liệu',detail:'Cần thêm dữ liệu để so sánh.'};
    if(a===b)return {type:'same',tone:'neutral',label:'Đồng Chi',detail:`Cùng Địa Chi ${MysticalData.BRANCHES[a]}.`};
    const rel=this.relations(a);
    if(rel.trine.includes(b))return {type:'trine',tone:'positive',label:'Tam hợp',detail:`${MysticalData.BRANCHES[a]} và ${MysticalData.BRANCHES[b]} cùng nhóm ${this.trineInfo(a).name}.`};
    if(MysticalData.SIX_HARMONY[a]===b)return {type:'harmony',tone:'positive',label:'Lục hợp',detail:`${MysticalData.BRANCHES[a]} và ${MysticalData.BRANCHES[b]} là cặp Lục hợp.`};
    if(rel.clash===b)return {type:'clash',tone:'caution',label:'Lục xung',detail:`${MysticalData.BRANCHES[a]} ↔ ${MysticalData.BRANCHES[b]} là cặp đối xung trực tiếp.`};
    const group=this.fourClashInfo(a);
    if(group?.members.includes(b))return {type:'four-clash',tone:'caution',label:'Cùng Tứ hành xung',detail:`Cùng nhóm ${group.name}, nhưng không phải cặp đối xung trực tiếp.`};
    return {type:'neutral',tone:'neutral',label:'Trung tính',detail:'Không thuộc Tam hợp, Lục hợp hoặc cặp Lục xung trực tiếp.'};
  }
  static western(ds){const [,m,d]=ds.split('-').map(Number),md=m*100+d;let idx=0;if(md>=120&&md<=218)idx=1;else if(md>=219&&md<=320)idx=2;else if(md>=321&&md<=419)idx=3;else if(md>=420&&md<=520)idx=4;else if(md>=521&&md<=620)idx=5;else if(md>=621&&md<=722)idx=6;else if(md>=723&&md<=822)idx=7;else if(md>=823&&md<=922)idx=8;else if(md>=923&&md<=1022)idx=9;else if(md>=1023&&md<=1121)idx=10;else if(md>=1122&&md<=1221)idx=11;return {name:MysticalData.ZODIAC[idx][0],symbol:MysticalData.ZODIAC[idx][1],text:MysticalData.ZODIAC[idx][2]}}
  static zodiacRange(name){return ({'Ma Kết':'22/12 – 19/01','Bảo Bình':'20/01 – 18/02','Song Ngư':'19/02 – 20/03','Bạch Dương':'21/03 – 19/04','Kim Ngưu':'20/04 – 20/05','Song Tử':'21/05 – 20/06','Cự Giải':'21/06 – 22/07','Sư Tử':'23/07 – 22/08','Xử Nữ':'23/08 – 22/09','Thiên Bình':'23/09 – 22/10','Bọ Cạp':'23/10 – 21/11','Nhân Mã':'22/11 – 21/12'})[name]||'—'}
  static kuaForYear(year,gender){if(!['male','female'].includes(gender))return null;const factor=NumerologyCalculator.reduce(NumerologyCalculator.sumDigits(String(year).slice(-2)),false);let n;if(year>=2000)n=gender==='male'?9-factor:6+factor;else n=gender==='male'?10-factor:5+factor;n=NumerologyCalculator.reduce(n,false);if(n===0)n=9;if(n===5)n=gender==='male'?2:8;return {number:n,...MysticalData.KUA_INFO[n]}}
  static genderLabel(g){return g==='male'?'Nam':g==='female'?'Nữ':g==='other'?'Khác':'Chưa chọn'}
  static genderInsight(g,kua,yc,dc,hc){if(!kua)return g==='other'?'Cung phi Bát Trạch truyền thống dùng công thức phân biệt Nam/Nữ, nên hệ thống không tự quy đổi khi hồ sơ chọn “Khác”.':'Chọn Nam hoặc Nữ trong hồ sơ để kích hoạt lớp Cung phi. Can Chi, Tam hợp và đối xung vẫn được tính bình thường.';const focus=g==='male'?'Quan sát cách bạn dùng tính chủ động, trách nhiệm và ranh giới trong công việc lẫn quan hệ.':'Quan sát cách bạn cân bằng tự chủ, ranh giới và trách nhiệm cảm xúc trong quan hệ và công việc.';return `<strong>${this.genderLabel(g)} • Cung ${kua.gua} ${kua.element} • Quái số ${kua.number}.</strong> Thuộc <strong>${kua.group}</strong>; nhóm phương vị tham khảo: ${kua.directions}. ${focus} Trụ năm <strong>${yc.stem} ${yc.branch}</strong>, trụ ngày <strong>${dc.stem} ${dc.branch}</strong>${hc?` và trụ giờ <strong>${hc.stem} ${hc.branch}</strong>`:''} không đổi theo giới tính.`}
  static elementSummary(counts,total){
    const entries=Object.entries(counts).sort((a,b)=>b[1]-a[1]);
    const dominant=entries[0],missing=entries.filter(([,c])=>c===0).map(([e])=>e),unique=entries.filter(([,c])=>c>0).length;
    return {dominant:dominant?.[0]||'—',dominantCount:dominant?.[1]||0,missing,unique,total,diversity:Math.round(unique/5*100)};
  }

  static stemElementRelation(a,b){
    if(a===b)return {label:`Đồng hành ${a}`,tone:'neutral',detail:`Hai Thiên Can cùng hành ${a}; trong mô hình hiện tại đây là quan hệ đồng pha.`};
    if(MysticalData.GENERATES[a]===b)return {label:`${a} sinh ${b}`,tone:'positive',detail:`Hành ${a} tạo sinh cho ${b}; đọc như dòng hỗ trợ từ trục trước sang trục sau.`};
    if(MysticalData.GENERATES[b]===a)return {label:`${b} sinh ${a}`,tone:'positive',detail:`Hành ${b} tạo sinh cho ${a}; đọc như trục sau có khả năng bổ sung nguồn lực cho trục trước.`};
    if(MysticalData.CONTROLS[a]===b)return {label:`${a} khắc ${b}`,tone:'caution',detail:`Hành ${a} khắc ${b}; nên đọc như một điểm ma sát hoặc yêu cầu điều tiết, không mặc định là xấu.`};
    if(MysticalData.CONTROLS[b]===a)return {label:`${b} khắc ${a}`,tone:'caution',detail:`Hành ${b} khắc ${a}; mô hình gợi một quan hệ cần quản trị thay vì để hai xu hướng kéo ngược nhau.`};
    return {label:'Quan hệ gián tiếp',tone:'neutral',detail:'Không có quan hệ sinh/khắc trực tiếp trong chu trình Ngũ hành đang dùng.'};
  }
  static polaritySummary(pillars){
    const values=[];pillars.forEach(x=>{if(!x)return;values.push(MysticalData.STEM_POLARITY[x.stemIndex],MysticalData.BRANCH_POLARITY[x.branchIndex])});
    const yang=values.filter(x=>x==='Dương').length,yin=values.length-yang;
    const label=Math.abs(yang-yin)<=1?'Tương đối cân bằng':yang>yin?'Nghiêng Dương':'Nghiêng Âm';
    return {yang,yin,total:values.length,label};
  }
  static expertReading(profile,d){
    const {yc,dc,hc,z,selectedKua,relationMatrix,elementSummary}=d;
    const yDay=this.stemElementRelation(yc.element,dc.element),dHour=hc?this.stemElementRelation(dc.element,hc.element):null,pol=this.polaritySummary([yc,dc,hc]);
    const positives=relationMatrix.filter(x=>x.tone==='positive').length,cautions=relationMatrix.filter(x=>x.tone==='caution').length;
    const branchConclusion=positives>cautions?'cấu trúc Chi thiên về liên kết/hỗ trợ':cautions>positives?'cấu trúc Chi có nhiều điểm ma sát cần quản trị':'cấu trúc Chi tương đối cân bằng, không có một hướng áp đảo';
    return `<div class="expert-report">
      <section class="expert-section expert-lead"><span class="expert-kicker">KẾT LUẬN ĐIỀU HÀNH</span><h4>${dc.stem} ${dc.branch} làm trục tham chiếu ngày sinh</h4><p>Trong cách đọc Tứ trụ, <strong>Thiên Can ngày</strong> thường được dùng làm mốc Nhật chủ. Bản ứng dụng này chỉ dùng trụ ngày như <strong>trục tham chiếu một phần</strong> vì chưa tính trụ tháng và không đánh giá vượng/suy, dụng thần hay đại vận. Với dữ liệu hiện có, Nhật Can <strong>${dc.stem} — ${dc.element}</strong> gợi mô-típ ${MysticalData.ELEMENT_TEXT[dc.element]}; còn ma trận Địa Chi cho thấy <strong>${branchConclusion}</strong>.</p></section>
      <section class="expert-section"><span class="expert-kicker">1. THIÊN CAN NĂM ↔ NGÀY</span><h4>${yc.stem} ${yc.element} ↔ ${dc.stem} ${dc.element} · ${yDay.label}</h4><p>${yDay.detail} Trụ năm thường được ứng dụng này dùng như lớp bối cảnh/gốc tuổi, trong khi trụ ngày làm mốc vận hành cá nhân. Vì vậy, quan hệ này hữu ích để quan sát xem môi trường nền và cách phản ứng cá nhân đang bổ trợ hay tạo ma sát.</p></section>
      ${hc?`<section class="expert-section"><span class="expert-kicker">2. THIÊN CAN NGÀY ↔ GIỜ</span><h4>${dc.stem} ${dc.element} ↔ ${hc.stem} ${hc.element} · ${dHour.label}</h4><p>${dHour.detail} Trong mô hình ứng dụng, trụ giờ được xem như lớp bổ sung cho cách biểu hiện ở phạm vi riêng tư/mục tiêu về sau; đây là diễn giải tham khảo chứ không thay thế Bát tự đầy đủ.</p></section>`:''}
      <section class="expert-section"><span class="expert-kicker">${hc?'3':'2'}. MA TRẬN ĐỊA CHI</span><h4>${positives} hỗ trợ · ${cautions} ma sát · ${relationMatrix.length-positives-cautions} trung tính</h4><p>${relationMatrix.map(x=>`<strong>${x.from}–${x.to}:</strong> ${x.a} ↔ ${x.b} = ${x.label}`).join(' · ')}. Khi có Lục xung/Tứ hành xung, nên đọc là vùng có xu hướng cần điều tiết hoặc thay đổi nhịp; không đồng nhất với “xấu”. Khi có Tam hợp/Lục hợp, đọc là vùng có tính liên kết dễ hình thành hơn.</p></section>
      <section class="expert-section"><span class="expert-kicker">${hc?'4':'3'}. ÂM DƯƠNG & NGŨ HÀNH</span><h4>${pol.label} · Dương ${pol.yang}/${pol.total} · Âm ${pol.yin}/${pol.total}</h4><p>Phân bố Âm/Dương hiện chỉ đếm Can và Chi của các trụ đang có dữ liệu. Thiên Can nổi bật là hành <strong>${elementSummary.dominant}</strong> (${elementSummary.dominantCount}/${elementSummary.total}). ${elementSummary.missing.length?`Các hành chưa xuất hiện ở lớp Thiên Can đang xét: <strong>${elementSummary.missing.join(', ')}</strong>.`:'Các hành đều có mặt trong dữ liệu đang xét.'} Không nên dùng thống kê này để kết luận cân bằng Ngũ hành toàn lá số vì thiếu trụ tháng và các lớp tàng can.</p></section>
      <section class="expert-section"><span class="expert-kicker">${hc?'5':'4'}. CUNG PHI & CUNG HOÀNG ĐẠO</span><h4>${selectedKua?`Cung ${selectedKua.gua} ${selectedKua.element} · ${selectedKua.group}`:'Chưa áp dụng Cung phi'} · ${z.name}</h4><p>${selectedKua?`Cung phi được tính theo giới tính và năm âm lịch trong công thức truyền thống của ứng dụng; nên dùng chủ yếu cho lớp tham khảo phương vị.`:'Chưa chọn Nam/Nữ nên hệ thống không ép quy đổi Cung phi.'} Cung hoàng đạo <strong>${z.name}</strong> bổ sung một mô-típ phương Tây: ${z.text}. Hai hệ quy chiếu này nên được đọc tách lớp, không cộng gộp thành một “điểm số số mệnh”.</p></section>
      <section class="expert-section expert-caution"><span class="expert-kicker">GIỚI HẠN MÔ HÌNH</span><h4>Chưa phải lá số Bát tự/Tử vi hoàn chỉnh</h4><p>Ứng dụng hiện có trụ năm, ngày và giờ; chưa dùng trụ tháng, tiết khí đầy đủ, tàng can, thập thần, vượng suy, dụng thần, đại vận/lưu niên. Vì vậy phần trên là <strong>phân tích cấu trúc Can Chi có kiểm soát</strong>, phù hợp để tham khảo và học hệ quy chiếu hơn là dự đoán chắc chắn tương lai.</p></section>
    </div>`;
  }

  static analyze(profile){
    const birth=new Date(profile.birthDate+'T12:00:00'),yc=this.yearCanChi(birth.getFullYear()),dc=this.dayCanChi(birth),hc=this.hourCanChi(birth,profile.birthTime),lunar=LunarConverter.fromDate(birth),z=this.western(profile.birthDate),rel=this.relations(yc.branchIndex),tri=this.trineInfo(yc.branchIndex),four=this.fourClashInfo(yc.branchIndex),harm=MysticalData.SIX_HARMONY[yc.branchIndex];
    const maleKua=this.kuaForYear(lunar.year,'male'),femaleKua=this.kuaForYear(lunar.year,'female'),selectedKua=this.kuaForYear(lunar.year,profile.gender);
    const elements=[yc.element,dc.element,...(hc?[hc.element]:[])],counts={Mộc:0,Hỏa:0,Thổ:0,Kim:0,Thủy:0};elements.forEach(e=>counts[e]++);const total=elements.length,elementSummary=this.elementSummary(counts,total);
    const relationsMain=[
      ['Địa Chi năm sinh',this.branchFull(yc.branchIndex),`Tuổi ${yc.animal}; đây là Chi làm mốc cho các quan hệ bên dưới.`],
      ['Tam hợp',`${tri.name} • ${tri.bureau}`,`Ba Chi trong nhóm: ${tri.members.map(i=>this.branchFull(i)).join(' • ')}.`],
      ['Lục hợp / Nhị hợp',`${this.branchFull(yc.branchIndex)} ↔ ${this.branchFull(harm)}`,`Cặp hợp trực tiếp của Chi ${yc.branch} là ${MysticalData.BRANCHES[harm]}.`],
      ['Lục xung / Đối xung',`${this.branchFull(yc.branchIndex)} ↔ ${this.branchFull(rel.clash)}`,`Đây là Chi nằm đối diện trực tiếp với ${yc.branch} trong vòng 12 Địa Chi.`],
      ['Tứ hành xung',four.name,`Nhóm gồm: ${four.members.map(i=>this.branchFull(i)).join(' • ')}. Không phải mọi cặp trong nhóm đều đối xung trực tiếp.`]
    ];
    const relationExtra=[['Chi ngày sinh',this.branchFull(dc.branchIndex),`So với Chi năm ${yc.branch}: ${this.relationBetween(yc.branchIndex,dc.branchIndex)}.`],['Chi giờ sinh',hc?this.branchFull(hc.branchIndex):'Chưa nhập giờ sinh',hc?`So với Chi năm ${yc.branch}: ${this.relationBetween(yc.branchIndex,hc.branchIndex)}.`:'Nhập giờ sinh để xác định Địa Chi giờ.'],['Nam cùng năm sinh',`${tri.name} • đối xung ${yc.branch} ↔ ${MysticalData.BRANCHES[rel.clash]}`,'Các quan hệ Địa Chi không đổi theo giới tính.'],['Nữ cùng năm sinh',`${tri.name} • đối xung ${yc.branch} ↔ ${MysticalData.BRANCHES[rel.clash]}`,'Khác biệt Nam/Nữ nằm ở Cung phi, không phải Tam hợp.']];
    const relationMatrix=[
      {from:'Năm',to:'Ngày',a:yc.branch,b:dc.branch,...this.relationDescriptor(yc.branchIndex,dc.branchIndex)},
      ...(hc?[{from:'Năm',to:'Giờ',a:yc.branch,b:hc.branch,...this.relationDescriptor(yc.branchIndex,hc.branchIndex)},{from:'Ngày',to:'Giờ',a:dc.branch,b:hc.branch,...this.relationDescriptor(dc.branchIndex,hc.branchIndex)}]:[])
    ];
    const positives=relationMatrix.filter(x=>x.tone==='positive').length,cautions=relationMatrix.filter(x=>x.tone==='caution').length;
    const structureLabel=positives>cautions?'Thiên về liên kết':cautions>positives?'Có điểm ma sát cần đọc kỹ':'Cân bằng / trung tính';
    const deepInsights=[
      {label:'CẤU TRÚC ĐỊA CHI',value:structureLabel,detail:`Trong ${relationMatrix.length} cặp trụ có dữ liệu: ${positives} quan hệ hỗ trợ, ${cautions} quan hệ cần lưu ý và ${relationMatrix.length-positives-cautions} quan hệ trung tính/đồng Chi.`},
      {label:'THIÊN CAN NỔI BẬT',value:elementSummary.dominant,detail:`Hành ${elementSummary.dominant} xuất hiện ${elementSummary.dominantCount}/${total} Thiên Can đang có dữ liệu. ${elementSummary.missing.length?`Chưa xuất hiện: ${elementSummary.missing.join(', ')}.`:'Cả năm hành đều có mặt trong dữ liệu đang xét.'}`},
      {label:'CUNG PHI',value:selectedKua?`${selectedKua.gua} • ${selectedKua.element}`:'Chưa áp dụng',detail:selectedKua?`Quái số ${selectedKua.number}, thuộc ${selectedKua.group}. Đây là lớp thay đổi theo Nam/Nữ trong mô hình hiện tại.`:'Cần chọn Nam hoặc Nữ nếu muốn áp dụng công thức Cung phi truyền thống.'}
    ];
    const partial={birth,yc,dc,hc,lunar,z,rel,tri,four,harm,maleKua,femaleKua,selectedKua,counts,total,elementSummary,relationsMain,relationExtra,relationMatrix,deepInsights};
    const reading=this.expertReading(profile,partial);
    return {...partial,reading};
  }
}


/* ===== models/tarot-engine.js ===== */

/** Pure Tarot model. Deterministic by profile + query + calendar day. */
class TarotEngine{
  static hash(str){let h=2166136261>>>0;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
  static rng(seed){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=seed;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
  static normalize(q){return(q||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^\p{L}\p{N}]+/gu,' ').trim()}
  static topicInterpret(topic,position,meaning){const lens=MysticalData.TOPIC_LENS[topic]||MysticalData.TOPIC_LENS.general,verbs=['Nền tảng của vấn đề đang gợi','Trọng tâm hiện tại đang cho thấy','Hướng xử lý đáng cân nhắc là'];return `${verbs[position]} ${lens[position]}: ${meaning}.`}
  static phase(cardIndex){if(cardIndex<=6)return {key:'initiation',rank:1,label:'Khởi mở & lựa chọn',detail:'nhóm 0–VI thường được dùng để soi cách một hành trình, giá trị hoặc lựa chọn đang hình thành'};if(cardIndex<=11)return {key:'agency',rank:2,label:'Ý chí & điều chỉnh',detail:'nhóm VII–XI nhấn mạnh khả năng điều hướng, sức bền, trách nhiệm và cân bằng'};if(cardIndex<=16)return {key:'transform',rank:3,label:'Chuyển hóa & tái cấu trúc',detail:'nhóm XII–XVI thường gợi việc đổi góc nhìn, buông cũ hoặc tái cấu trúc'};return {key:'integrate',rank:4,label:'Hồi phục & tích hợp',detail:'nhóm XVII–XXI thường nghiêng về định hướng, sáng rõ, tổng kết và tích hợp'}}

  static synthesize(picks,meanings,mode,topic){
    const upright=picks.filter(p=>!p.reversed).length,reversed=picks.length-upright;
    const phases=picks.reduce((acc,p)=>{const phase=this.phase(p.cardIndex);acc[phase.key]=(acc[phase.key]||{...phase,count:0});acc[phase.key].count++;return acc},{});
    const dominant=Object.values(phases).sort((a,b)=>b.count-a.count)[0],avgIndex=picks.reduce((s,p)=>s+p.cardIndex,0)/picks.length;
    const tempo=avgIndex<7?'Năng lượng mở đầu':avgIndex<14?'Giai đoạn điều chỉnh':'Giai đoạn tích hợp';
    const orientation=reversed===0?'Dòng chảy khá trực tiếp':reversed>=Math.ceil(picks.length/2)?'Nhiều điểm cần rà soát':'Có cả thuận dòng và điểm cần xem lại';
    const focus=mode==='auto'?'toàn cảnh sáu vùng':`chủ đề ${MysticalData.TOPIC_NAME[topic]?.toLowerCase()||'đang xem'}`;
    const phaseRanks=picks.map(p=>this.phase(p.cardIndex).rank),direction=phaseRanks.at(-1)-phaseRanks[0];
    const movement=direction>=2?'Dịch chuyển mạnh về phía tích hợp / hoàn tất':direction===1?'Có xu hướng tiến sang giai đoạn kế tiếp':direction===0?'Các lá đang xoay quanh cùng một tầng vấn đề':'Có xu hướng quay lại xử lý nền tảng hoặc vấn đề chưa hoàn tất';
    const reversedPositions=picks.map((p,i)=>p.reversed?i:null).filter(i=>i!==null);
    return {upright,reversed,dominant,tempo,orientation,movement,reversedPositions,
      cards:[
        {label:'XUÔI / NGƯỢC',value:`${upright} / ${reversed}`,detail:`${orientation}. Lá ngược được dùng như dấu hiệu cần rà soát, không mặc định là tiêu cực.`},
        {label:'PHA NỔI BẬT',value:dominant?.label||'—',detail:dominant?`${dominant.count}/${picks.length} lá nằm trong pha “${dominant.label}”; ${dominant.detail}.`:'—'},
        {label:'NHỊP TRẢI BÀI',value:tempo,detail:`Chỉ số thứ tự trung bình của Major Arcana là ${avgIndex.toFixed(1)}/21; mô tả nhịp biểu tượng của ${focus}, không phải xác suất dự báo.`}
      ],
      thread:`Mạch chung đang nghiêng về <strong>${dominant?.label||'nhiều lớp khác nhau'}</strong>. ${orientation}. Về hướng dịch chuyển, trải bài cho thấy <strong>${movement.toLowerCase()}</strong>.`};
  }

  static expertSummary({mode,topic,picks,meanings,domains,synthesis}){
    if(mode==='auto'){
      const priority=picks.map((p,i)=>({i,score:(p.reversed?3:0)+this.phase(p.cardIndex).rank})).sort((a,b)=>b.score-a.score).slice(0,2).map(x=>x.i);
      const p1=domains[priority[0]],p2=domains[priority[1]];
      return `<div class="expert-report">
        <section class="expert-section expert-lead"><span class="expert-kicker">KẾT LUẬN ĐIỀU HÀNH</span><h4>${synthesis.dominant?.label||'Nhiều lớp'} · ${synthesis.orientation}</h4><p>${synthesis.thread} Với trải bài sáu vùng, điều quan trọng không phải “lá nào tốt/xấu” mà là <strong>vùng nào đang đòi hỏi kiểm chứng và hành động nhiều nhất</strong>. Hai vùng nổi bật theo cấu trúc hiện tại là <strong>${p1?.title||'—'}</strong> và <strong>${p2?.title||'—'}</strong>.</p></section>
        <section class="expert-section"><span class="expert-kicker">1. CẤU TRÚC TRẢI BÀI</span><h4>${synthesis.upright} lá xuôi · ${synthesis.reversed} lá ngược</h4><p>${synthesis.reversed===0?'Không có lá ngược, nên mạch đọc khá trực tiếp; vẫn cần tránh đồng nhất “xuôi” với chắc chắn thuận lợi.':synthesis.reversed>=3?'Tỷ lệ lá ngược cao cho thấy nhiều vùng nên được đọc theo hướng rà soát giả định, giới hạn hoặc phần chưa vận hành trơn tru.':'Có một số điểm nghẽn nhưng không chiếm toàn bộ trải bài.'} ${synthesis.movement}.</p></section>
        ${domains.map((d,i)=>`<section class="expert-section"><span class="expert-kicker">${i+2}. ${d.title.toUpperCase()}</span><h4>${picks[i].card[1]} · ${picks[i].reversed?'Lá ngược':'Lá xuôi'}</h4><p>Trong vùng <strong>${d.lens}</strong>, tín hiệu chính là <strong>${meanings[i]}</strong>. Lá thuộc pha <strong>${this.phase(picks[i].cardIndex).label}</strong>. Khi kiểm chứng, hãy tìm một ví dụ thực tế trong 7–30 ngày gần nhất: quyết định nào, hành vi nào hoặc dữ kiện nào đang phản ánh đúng mô-típ này?</p></section>`).join('')}
        <section class="expert-section expert-caution"><span class="expert-kicker">PHƯƠNG PHÁP ĐỌC CHUYÊN SÂU</span><h4>Tách biểu tượng khỏi dự báo</h4><p>Hãy phân loại từng thông điệp thành ba nhóm: <strong>dữ kiện đã có</strong>, <strong>giả định cần kiểm chứng</strong> và <strong>hành động nằm trong quyền kiểm soát</strong>. Chỉ ưu tiên hành động khi ít nhất một thông điệp khớp với dữ liệu thực tế; không dùng trải bài thay cho quyết định y tế, pháp lý hoặc tài chính.</p></section>
      </div>`;
    }
    const mid=1,critical=synthesis.reversedPositions.includes(mid)?mid:(synthesis.reversedPositions[0]??mid),source=mode==='open'?`chủ đề ${MysticalData.TOPIC_NAME[topic].toLowerCase()}`:'câu hỏi đã chọn';
    return `<div class="expert-report">
      <section class="expert-section expert-lead"><span class="expert-kicker">KẾT LUẬN ĐIỀU HÀNH</span><h4>${synthesis.movement}</h4><p>Nền của ${source} là <strong>${meanings[0]}</strong>; điểm đang chi phối hiện tại chuyển sang <strong>${meanings[1]}</strong>; hướng xử lý được gợi bởi <strong>${meanings[2]}</strong>. Vì vậy, trọng tâm không phải đoán kết quả cuối cùng mà là nhận ra <strong>cơ chế chuyển từ trạng thái hiện tại sang hành động kế tiếp</strong>.</p></section>
      <section class="expert-section"><span class="expert-kicker">1. NGUYÊN NHÂN / NỀN TẢNG</span><h4>${picks[0].card[1]} · ${picks[0].reversed?'Ngược':'Xuôi'}</h4><p>${this.topicInterpret(topic,0,meanings[0])} Đây là lớp nên dùng để nhận diện bối cảnh đã hình thành vấn đề; tránh nhầm nguyên nhân nền với tình trạng nhất thời.</p></section>
      <section class="expert-section"><span class="expert-kicker">2. NÚT THẮT HIỆN TẠI</span><h4>${picks[1].card[1]} · ${picks[1].reversed?'Ngược':'Xuôi'}</h4><p>${this.topicInterpret(topic,1,meanings[1])} ${critical===1?'Lá trung tâm đồng thời là điểm cần rà soát mạnh nhất, nên đây là nơi đáng kiểm chứng trước tiên.':'Lá trung tâm là trục nối giữa nền tảng và hướng hành động.'}</p></section>
      <section class="expert-section"><span class="expert-kicker">3. HƯỚNG HÀNH ĐỘNG</span><h4>${picks[2].card[1]} · ${picks[2].reversed?'Ngược':'Xuôi'}</h4><p>${this.topicInterpret(topic,2,meanings[2])} Hãy chuyển thông điệp thành một hành động nhỏ có thời hạn 24–72 giờ; nếu không thể diễn đạt thành hành động kiểm chứng được, coi nó là câu hỏi phản tư thay vì kết luận.</p></section>
      <section class="expert-section"><span class="expert-kicker">4. CẤU TRÚC BIỂU TƯỢNG</span><h4>${synthesis.dominant?.label||'Nhiều lớp'} · ${synthesis.orientation}</h4><p>${synthesis.thread} Lá cần chú ý nhất theo cấu trúc là <strong>${picks[critical].card[1]}</strong>, vì nó ${picks[critical].reversed?'đang ở trạng thái ngược / cần rà soát':'nằm ở vị trí trung tâm của mạch diễn biến'}.</p></section>
      <section class="expert-section expert-caution"><span class="expert-kicker">5. KIỂM CHỨNG NGOÀI ĐỜI</span><h4>Ba câu hỏi bắt buộc trước khi kết luận</h4><p><strong>1)</strong> Dữ kiện nào đang xác nhận thông điệp? <strong>2)</strong> Tôi đang giả định điều gì mà chưa có bằng chứng? <strong>3)</strong> Việc nhỏ nhất tôi có thể làm để kiểm tra giả định trong 72 giờ là gì? Cách đọc này giúp Tarot giữ vai trò phản tư thay vì trở thành dự báo cứng.</p></section>
    </div>`;
  }

  static draw(profile,{mode,topic,question,presetQuestion},date=new Date()){
    let q='',qKey='',count=3,positions=[],domains=[];topic=mode==='auto'?'auto':topic;
    if(mode==='auto'){q='Toàn cảnh cá nhân hôm nay';qKey='auto-all';count=MysticalData.AUTO_DOMAINS.length;domains=MysticalData.AUTO_DOMAINS;positions=domains.map(x=>x.label)}
    else if(mode==='open'){q=`Không câu hỏi • ${MysticalData.TOPIC_NAME[topic]}`;qKey=`open-${topic}`;positions=['NỀN TẢNG','TRỌNG TÂM HIỆN TẠI','HƯỚNG TIẾP CẬN']}
    else if(mode==='preset'){q=presetQuestion||MysticalData.TAROT_PRESETS[topic][0];qKey=this.normalize(q);positions=['NỀN TẢNG','TRỌNG TÂM HIỆN TẠI','HƯỚNG TIẾP CẬN']}
    else{q=(question||'').trim();if(q.length<6)throw new Error('Hãy nhập câu hỏi rõ hơn (ít nhất 6 ký tự), hoặc chọn Auto/Không câu hỏi.');qKey=this.normalize(q);positions=['NỀN TẢNG','TRỌNG TÂM HIỆN TẠI','HƯỚNG TIẾP CẬN']}
    const today=Format.iso(date),base=[NumerologyCalculator.stripName(profile.fullName),profile.birthDate,profile.birthTime||'',profile.gender||'',profile.identityKey||'',mode,topic,qKey,today].join('|'),seed=this.hash(base),rand=this.rng(seed),pool=MysticalData.TAROT.map((_,i)=>i),picks=[];
    for(let i=0;i<count;i++){const idx=Math.floor(rand()*pool.length),ci=pool.splice(idx,1)[0];picks.push({card:MysticalData.TAROT[ci],cardIndex:ci,reversed:rand()<.32})}
    const meanings=picks.map(p=>p.reversed?p.card[3]:p.card[2]),yc=AstrologyCalculator.yearCanChi(new Date(profile.birthDate+'T12:00:00').getFullYear()),lp=NumerologyCalculator.lifePath(profile.birthDate),context=[mode==='auto'?'Auto toàn cảnh':mode==='open'?'Không câu hỏi':mode==='preset'?'Câu hỏi gợi ý':'Tự đặt câu hỏi',...(mode==='auto'?[]:[MysticalData.TOPIC_NAME[topic]]),`Ngày ${Format.vn(date,{day:'2-digit',month:'2-digit',year:'numeric'})}`,`Hồ sơ ${AstrologyCalculator.genderLabel(profile.gender)}`,`Số chủ đạo ${lp}`,`${yc.stem} ${yc.branch}`];
    const synthesis=this.synthesize(picks,meanings,mode,topic),summary=this.expertSummary({mode,topic,picks,meanings,domains,synthesis});
    const actions=mode==='auto'?[`Chọn 2 vùng có liên hệ thực tế rõ nhất và ghi 1 dữ kiện xác nhận cho mỗi vùng.`,`Với vùng ưu tiên, đặt một hành động có thể hoàn tất trong 72 giờ.`,`Nếu một lá ngược gây lo lắng, xác định điều gì đang nằm ngoài quyền kiểm soát và điều gì vẫn có thể xử lý.`,`Không rút lại chỉ để tìm kết quả dễ chịu hơn; chỉ đổi trải bài khi câu hỏi hoặc dữ liệu đầu vào thực sự thay đổi.`]:[`Ghi một dữ kiện đang củng cố hoặc bác bỏ thông điệp của lá trung tâm ${picks[1].card[1]}.`,`Chuyển lá thứ ba thành một hành động cụ thể trong 24–72 giờ.`,`Viết riêng “điều tôi biết” và “điều tôi đang suy đoán” để tránh nhập hai lớp thành một.`,`Nếu quyết định có hậu quả lớn, dùng Tarot như lớp phản tư bổ sung chứ không thay dữ liệu/chuyên môn thực tế.`];
    return {mode,topic,q,seed,session:(seed>>>0).toString(16).toUpperCase().padStart(8,'0'),positions,domains,picks,meanings,context,synthesis,summary,actions};
  }
}


/* ===== models/compatibility-calculator.js ===== */

/**
 * CompatibilityCalculator
 * Pure reference model for comparing two profiles.
 * Scores are internal visualization values only — NOT probabilities,
 * scientific measurements, diagnoses, or predictions of relationship success.
 */
class CompatibilityCalculator{
  static RELATION_TYPES={
    general:{label:'Tổng quan',weights:{core:.22,emotional:.22,communication:.22,canChi:.10,growth:.14,current:.10},focus:['core','communication','emotional']},
    love:{label:'Tình cảm / yêu đương',weights:{core:.18,emotional:.30,communication:.24,canChi:.08,growth:.12,current:.08},focus:['emotional','communication','core']},
    friendship:{label:'Bạn bè',weights:{core:.18,emotional:.20,communication:.30,canChi:.06,growth:.16,current:.10},focus:['communication','emotional','growth']},
    work:{label:'Công việc / cộng tác',weights:{core:.28,emotional:.08,communication:.30,canChi:.05,growth:.22,current:.07},focus:['communication','core','growth']},
    family:{label:'Gia đình',weights:{core:.22,emotional:.28,communication:.24,canChi:.08,growth:.10,current:.08},focus:['emotional','communication','core']}
  };

  static clamp(n,min=0,max=100){return Math.max(min,Math.min(max,Math.round(n)))}
  static mean(values){const valid=values.filter(Number.isFinite);return valid.length?valid.reduce((a,b)=>a+b,0)/valid.length:60}
  static stdev(values){const valid=values.filter(Number.isFinite);if(valid.length<2)return 0;const m=this.mean(valid);return Math.sqrt(valid.reduce((s,x)=>s+(x-m)**2,0)/valid.length)}

  static snapshot(profile,now=new Date()){
    if(!profile?.fullName?.trim()||!profile?.birthDate)throw new Error('Cần họ tên và ngày sinh của cả hai người để phân tích.');
    const birth=new Date(profile.birthDate+'T12:00:00');
    if(Number.isNaN(birth.getTime()))throw new Error('Ngày sinh không hợp lệ.');
    const year=AstrologyCalculator.yearCanChi(birth.getFullYear());
    const day=AstrologyCalculator.dayCanChi(birth);
    const hour=AstrologyCalculator.hourCanChi(birth,profile.birthTime||'');
    const lunar=LunarConverter.fromDate(birth);
    const zodiac=AstrologyCalculator.western(profile.birthDate);
    const kua=AstrologyCalculator.kuaForYear(lunar.year,profile.gender||'');
    const values={
      life:NumerologyCalculator.lifePath(profile.birthDate),
      expression:NumerologyCalculator.expression(profile.fullName),
      soul:NumerologyCalculator.soul(profile.fullName),
      personality:NumerologyCalculator.personality(profile.fullName),
      attitude:NumerologyCalculator.attitude(profile.birthDate),
      maturity:NumerologyCalculator.maturity(profile.fullName,profile.birthDate),
      personalYear:NumerologyCalculator.personalYear(profile.birthDate,now.getFullYear())
    };
    return {profile:{...profile},birth,year,day,hour,lunar,zodiac,kua,values};
  }

  static numericPair(label,a,b,detail=''){
    const x=NumerologyCalculator.alignment(a,b);
    return {label,score:x.score,state:x.state,a,b,detail:detail||`So sánh ${a} ↔ ${b} bằng khoảng cách số học sau rút gọn.`};
  }

  static branchPair(a,b){
    const r=AstrologyCalculator.relationDescriptor(a,b);
    const score={trine:86,harmony:89,same:70,clash:36,'four-clash':47,neutral:60,missing:60}[r.type]??60;
    return {...r,score};
  }

  static elementPair(a,b){
    if(a===b)return {score:78,label:`Đồng hành ${a}`,tone:'positive',detail:`Hai Thiên Can năm cùng hành ${a}. Mô hình đọc đây là một lớp dễ hiểu nhịp của nhau, nhưng hành vi thực tế vẫn có thể rất khác.`};
    if(MysticalData.GENERATES[a]===b||MysticalData.GENERATES[b]===a){
      const from=MysticalData.GENERATES[a]===b?a:b,to=MysticalData.GENERATES[a]===b?b:a;
      return {score:81,label:`Tương sinh ${from} → ${to}`,tone:'positive',detail:'Quan hệ tương sinh được xem là khả năng bổ trợ trong hệ Ngũ hành. Không nên diễn giải thành một người phải “nuôi” hoặc chịu trách nhiệm cho người kia.'};
    }
    if(MysticalData.CONTROLS[a]===b||MysticalData.CONTROLS[b]===a){
      const from=MysticalData.CONTROLS[a]===b?a:b,to=MysticalData.CONTROLS[a]===b?b:a;
      return {score:47,label:`Tương khắc ${from} ↔ ${to}`,tone:'caution',detail:'Quan hệ khắc được dùng như một câu hỏi về khác biệt cách điều tiết, quyết định hoặc ưu tiên. Không mặc định đây là “không hợp”.'};
    }
    return {score:61,label:'Quan hệ Ngũ hành gián tiếp',tone:'neutral',detail:'Không có quan hệ sinh/khắc trực tiếp theo chu trình Ngũ hành đang dùng.'};
  }

  static kuaPair(a,b){
    if(!a||!b)return {score:60,label:'Chưa đủ dữ liệu Cung phi',tone:'neutral',detail:'Cần giới tính Nam/Nữ theo công thức truyền thống ở cả hai hồ sơ để so lớp Cung phi. Thiếu dữ liệu này không ảnh hưởng các trục chính.'};
    if(a.gua===b.gua)return {score:80,label:`Cùng cung ${a.gua}`,tone:'positive',detail:`Hai hồ sơ quy về cùng cung ${a.gua}. Đây chỉ là lớp Bát Trạch đơn giản, không phải phép hợp hôn hoàn chỉnh.`};
    if(a.group===b.group)return {score:74,label:`Cùng ${a.group}`,tone:'positive',detail:`Hai cung cùng nhóm ${a.group}. Mô hình chỉ cộng nhẹ vì đây là lớp tham khảo phụ.`};
    return {score:53,label:'Khác nhóm Cung phi',tone:'neutral',detail:`Hai hồ sơ thuộc hai nhóm Cung phi khác nhau. Không dùng riêng yếu tố này để kết luận hợp/khắc.`};
  }

  static zodiacElement(name){
    const map={'Bạch Dương':'Hỏa','Sư Tử':'Hỏa','Nhân Mã':'Hỏa','Kim Ngưu':'Thổ','Xử Nữ':'Thổ','Ma Kết':'Thổ','Song Tử':'Khí','Thiên Bình':'Khí','Bảo Bình':'Khí','Cự Giải':'Thủy','Bọ Cạp':'Thủy','Song Ngư':'Thủy'};
    return map[name]||'—';
  }

  static zodiacPair(a,b){
    const ea=this.zodiacElement(a.name),eb=this.zodiacElement(b.name);
    if(ea===eb)return {score:76,label:`Cùng nhóm ${ea}`,detail:`${a.name} và ${b.name} cùng nhóm nguyên tố phương Tây ${ea}. Ứng dụng chỉ dùng lớp này với trọng số thấp.`};
    const key=[ea,eb].sort().join('|');
    if(new Set(['Hỏa|Khí','Thổ|Thủy']).has(key))return {score:79,label:`Nhóm ${ea} ↔ ${eb} bổ trợ`,detail:'Theo hệ quy chiếu cung phương Tây đơn giản, hai nhóm có thể bổ trợ. Đây chỉ là lớp phụ.'};
    if(new Set(['Hỏa|Thủy','Khí|Thổ']).has(key))return {score:53,label:`Nhóm ${ea} ↔ ${eb} tương phản`,detail:'Hai nhóm có khác biệt về cách phản ứng/ưu tiên theo mô hình cung phương Tây. Không phải dự báo chất lượng quan hệ.'};
    return {score:61,label:`Nhóm ${ea} ↔ ${eb} khác nhịp`,detail:'Hai nhóm không nằm trong cặp bổ trợ trực tiếp của mô hình đơn giản đang dùng.'};
  }

  static dimension(label,score,detail,components=[],short=''){return {label,score:this.clamp(score),detail,components,short}}

  static scoreState(score){
    if(score>=80)return 'Rất thuận';
    if(score>=68)return 'Khá thuận';
    if(score>=56)return 'Có thể phối hợp';
    if(score>=44)return 'Cần chủ động';
    return 'Khác nhịp rõ';
  }

  static effortLevel(index){
    if(index<=22)return {label:'Thấp',text:'Phần lớn khác biệt có thể xử lý bằng giao tiếp bình thường; vẫn cần kiểm chứng bằng hành vi thật.'};
    if(index<=36)return {label:'Vừa',text:'Có một vài vùng cần thống nhất cách giao tiếp, kỳ vọng hoặc nhịp hỗ trợ thay vì để mọi thứ tự vận hành.'};
    if(index<=50)return {label:'Khá cao',text:'Khác biệt tập trung ở những trục quan trọng; cần quy ước rõ và xem hai người có thực sự sẵn sàng điều chỉnh hay không.'};
    return {label:'Cao',text:'Mô hình cho thấy nhiều trục khác nhịp. Điều quan trọng là kiểm tra khả năng tôn trọng, thương lượng và thay đổi hành vi ngoài đời thực.'};
  }

  static pattern(dim){
    const {core,emotional,communication,growth,current}=dim;
    if(core.score>=72&&communication.score<58)return {title:'Cùng hướng, khác cách nói',text:'Hai người có thể hiểu tương đối giống điều mình muốn xây dựng, nhưng cách diễn đạt hoặc xử lý bất đồng dễ lệch nhịp. Điểm mấu chốt là quy ước cách nói chuyện khi căng thẳng.'};
    if(communication.score>=72&&core.score<58)return {title:'Dễ kết nối, cần thống nhất chuyện lớn',text:'Tương tác có thể khá trôi chảy, nhưng mục tiêu dài hạn hoặc tiêu chuẩn ưu tiên cần được nói rõ trước những quyết định lớn.'};
    if(emotional.score>=74&&current.score<56)return {title:'Gần về cảm xúc, lệch nhịp giai đoạn',text:'Hai người có khả năng hiểu nhu cầu của nhau nhưng đang ở hai nhịp ưu tiên khác nhau. Không nên ép đồng tốc; nên thống nhất thời gian và mức hỗ trợ thực tế.'};
    if(growth.score>=72&&communication.score>=66)return {title:'Bổ trợ để cùng phát triển',text:'Khác biệt có xu hướng tạo giá trị khi hai người biết phân vai và phản hồi rõ. Rủi ro là biến “bổ trợ” thành việc một người gánh thay người kia.'};
    if(core.score>=70&&emotional.score>=70&&communication.score>=70)return {title:'Đồng điệu khá đều',text:'Nhiều trục nền tảng đang cùng nhịp. Điều cần tránh là chủ quan rằng “đã hợp thì không cần nói rõ”; quan hệ tốt vẫn cần ranh giới và cam kết cụ thể.'};
    if(core.score<55&&emotional.score<55&&communication.score<55)return {title:'Khác biệt nền tảng khá rõ',text:'Mô hình không cho thấy nhiều vùng tự động cùng nhịp. Nếu mối quan hệ quan trọng, nên kiểm tra trực tiếp giá trị sống, cách xử lý bất đồng và mức sẵn sàng điều chỉnh.'};
    return {title:'Hợp theo kiểu bổ trợ',text:'Hai người có cả vùng đồng điệu và vùng khác biệt. Kết quả tốt nhất thường đến khi biết phần nào nên thuận theo nhau và phần nào cần thương lượng có chủ đích.'};
  }

  static profileVoice(snapshot){
    const info=MysticalData.NUM_TEXT[snapshot.values.life]||[`Số ${snapshot.values.life}`,'một xu hướng vận hành riêng','quan sát cách mình phản ứng trong thực tế'];
    return {title:`${snapshot.values.life} — ${info[0]}`,text:`${snapshot.profile.fullName} có trục Chủ đạo ${snapshot.values.life}, thường được mô tả theo hướng ${info[1]}. Khi đặt trong quan hệ, điểm đáng quan sát là ${info[2]}.`};
  }

  static contextPrompts(type,challenges,A,B){
    const base={
      general:[
        'Điều gì trong 1–2 năm tới là ưu tiên lớn nhất của mỗi người, và hai ưu tiên đó có thể cùng tồn tại không?',
        'Khi một người căng thẳng, người đó muốn được lắng nghe, có không gian riêng hay muốn cùng tìm giải pháp?',
        'Khi bất đồng, điều gì khiến mỗi người cảm thấy vẫn được tôn trọng?'
      ],
      love:[
        'Mỗi người hiểu “cam kết” và “được quan tâm” bằng những hành vi cụ thể nào?',
        'Khi ghen, hụt hẫng hoặc cần khoảng riêng, hai người muốn đối phương phản hồi ra sao?',
        'Những vấn đề lớn như tiền bạc, gia đình, công việc và ranh giới với người khác có điểm nào cần nói sớm?'
      ],
      friendship:[
        'Hai người kỳ vọng mức độ liên lạc, hỗ trợ và riêng tư trong tình bạn như thế nào?',
        'Khi một người bận hoặc cần khoảng cách, người còn lại có dễ hiểu sai thành xa cách hay không?',
        'Hai người giải quyết chuyện không hài lòng bằng nói thẳng, im lặng hay tránh né?'
      ],
      work:[
        'Ai chịu trách nhiệm quyết định cuối cùng ở từng loại việc và tiêu chí đánh giá kết quả là gì?',
        'Hai người thích phản hồi trực tiếp ngay hay cần thời gian suy nghĩ trước khi trả lời?',
        'Khi ưu tiên xung đột, nguyên tắc nào sẽ được dùng để chốt thay vì dựa vào cảm tính?'
      ],
      family:[
        'Mỗi người cần mức độ gần gũi và riêng tư như thế nào để vừa kết nối vừa không bị quá tải?',
        'Khi gia đình có mâu thuẫn, ai thường chủ động nói chuyện và ai cần thời gian lắng xuống?',
        'Những kỳ vọng về trách nhiệm, tiền bạc, chăm sóc và ranh giới với người thân đã được nói rõ chưa?'
      ]
    };
    const focus=challenges[0]?.label?.toLowerCase()||'khác biệt';
    const arr=(base[type]||base.general).slice();
    arr[2]+=` Hiện mô hình đang gợi ý chú ý thêm đến ${focus}.`;
    return arr.map((q,i)=>({number:i+1,question:q}));
  }

  static analyze(profileA,profileB,relationType='general',now=new Date()){
    const type=this.RELATION_TYPES[relationType]?relationType:'general';
    const relation=this.RELATION_TYPES[type];
    const A=this.snapshot(profileA,now),B=this.snapshot(profileB,now);

    const life=this.numericPair('Số chủ đạo',A.values.life,B.values.life);
    const maturity=this.numericPair('Số trưởng thành',A.values.maturity,B.values.maturity);
    const soul=this.numericPair('Số linh hồn',A.values.soul,B.values.soul);
    const expression=this.numericPair('Số biểu đạt',A.values.expression,B.values.expression);
    const personality=this.numericPair('Số nhân cách',A.values.personality,B.values.personality);
    const attitude=this.numericPair('Số thái độ',A.values.attitude,B.values.attitude);
    const current=this.numericPair('Năm cá nhân hiện tại',A.values.personalYear,B.values.personalYear);
    const crossAB=this.numericPair('Nhu cầu A ↔ cách thể hiện B',A.values.soul,B.values.personality);
    const crossBA=this.numericPair('Nhu cầu B ↔ cách thể hiện A',B.values.soul,A.values.personality);

    const branch=this.branchPair(A.year.branchIndex,B.year.branchIndex);
    const element=this.elementPair(A.year.element,B.year.element);
    const kua=this.kuaPair(A.kua,B.kua);
    const zodiac=this.zodiacPair(A.zodiac,B.zodiac);

    const dimensions={
      core:this.dimension('Giá trị & hướng sống',this.mean([life.score,maturity.score]),`Chủ đạo ${A.values.life} ↔ ${B.values.life}; Trưởng thành ${A.values.maturity} ↔ ${B.values.maturity}. Trục này dùng để soi mức độ dễ hiểu mục tiêu, nhịp ra quyết định và hướng phát triển dài hạn của nhau.`,[life,maturity],''),
      emotional:this.dimension('Nhu cầu cảm xúc',this.mean([soul.score,crossAB.score,crossBA.score,zodiac.score*.35+60*.65]),`Đối chiếu Linh hồn và tương quan giữa nhu cầu bên trong với cách người kia thường biểu hiện ra ngoài. Cung phương Tây chỉ tham gia ở mức rất thấp.`,[soul,crossAB,crossBA,zodiac],''),
      communication:this.dimension('Giao tiếp & biểu đạt',this.mean([expression.score,personality.score,attitude.score]),`Biểu đạt ${A.values.expression} ↔ ${B.values.expression}; Nhân cách ${A.values.personality} ↔ ${B.values.personality}; Thái độ ${A.values.attitude} ↔ ${B.values.attitude}. Đây là trục nên kiểm chứng bằng cách hai người xử lý hiểu lầm và phản hồi.`,[expression,personality,attitude],''),
      canChi:this.dimension('Can Chi & Ngũ hành',this.mean([branch.score,element.score,kua.score]),`${branch.label}; ${element.label}; ${kua.label}. Đây là lớp văn hóa/truyền thống và được giảm trọng số trong điểm tổng.`,[branch,element,kua],''),
      growth:this.dimension('Phát triển & bổ trợ',this.mean([maturity.score,life.score,expression.score]),`Trục này đọc khả năng phân vai, học hỏi và hỗ trợ nhau phát triển. Khác biệt có thể có lợi nếu hai người không biến “bổ trợ” thành phụ thuộc hoặc gánh thay.`,[maturity,life,expression],''),
      current:this.dimension('Nhịp hiện tại',current.score,`Năm cá nhân ${A.values.personalYear} ↔ ${B.values.personalYear}. Đây là lớp thay đổi theo năm nên không được dùng như một đặc điểm cố định của mối quan hệ.`,[current],'')
    };

    dimensions.core.short=dimensions.core.score>=72?'Dễ hiểu hướng đi của nhau':dimensions.core.score>=58?'Có điểm chung, vẫn cần chốt ưu tiên':'Kỳ vọng dài hạn có thể khác nhau';
    dimensions.emotional.short=dimensions.emotional.score>=72?'Nhu cầu bên trong khá dễ đọc nhau':dimensions.emotional.score>=58?'Có thể hiểu nhau nếu nói rõ nhu cầu':'Dễ kỳ vọng người kia tự hiểu';
    dimensions.communication.short=dimensions.communication.score>=72?'Cách trao đổi khá cùng nhịp':dimensions.communication.score>=58?'Giao tiếp được, cần quy ước khi căng thẳng':'Dễ nói cùng việc nhưng khác “ngôn ngữ”';
    dimensions.canChi.short=dimensions.canChi.score>=72?'Lớp truyền thống tương đối thuận':dimensions.canChi.score>=55?'Lớp truyền thống trung tính':'Có vài dấu hiệu tương phản truyền thống';
    dimensions.growth.short=dimensions.growth.score>=72?'Dễ bổ trợ khi biết phân vai':dimensions.growth.score>=58?'Có tiềm năng bổ trợ có điều kiện':'Cần tránh biến khác biệt thành cạnh tranh';
    dimensions.current.short=dimensions.current.score>=72?'Đang khá đồng nhịp giai đoạn':dimensions.current.score>=58?'Nhịp hiện tại không quá xa':'Đang khác tốc độ hoặc ưu tiên';

    const weights=relation.weights;
    const overall=this.clamp(Object.entries(weights).reduce((sum,[key,w])=>sum+dimensions[key].score*w,0));
    const label=overall>=80?'Nhiều vùng đang cùng nhịp':overall>=68?'Khá dễ phối hợp':overall>=58?'Có nền tảng nhưng cần chủ động':overall>=46?'Khác biệt đáng kể':'Khác nhịp ở nhiều trục';
    const sorted=Object.values(dimensions).slice().sort((a,b)=>b.score-a.score);
    const strengths=sorted.filter(x=>x.label!=='Can Chi & Ngũ hành').slice(0,2);
    const challenges=sorted.filter(x=>x.label!=='Can Chi & Ngũ hành').slice(-2).reverse();

    const relationalKeys=['core','emotional','communication','growth'];
    const relationalWeightSum=relationalKeys.reduce((s,k)=>s+weights[k],0);
    const naturalFit=this.clamp(relationalKeys.reduce((s,k)=>s+dimensions[k].score*weights[k],0)/relationalWeightSum);
    const lowestRelational=relationalKeys.map(k=>dimensions[k]).sort((a,b)=>a.score-b.score).slice(0,2);
    const effortIndex=this.clamp(100-this.mean(lowestRelational.map(x=>x.score)));
    const effort=this.effortLevel(effortIndex);
    const pattern=this.pattern(dimensions);
    const spread=this.stdev(Object.values(dimensions).map(x=>x.score));
    const spreadLabel=spread<9?'Các chiều khá đồng đều':spread<16?'Có vài chiều phân hóa':'Kết quả phân hóa mạnh';

    const focusNames=relation.focus.map(k=>dimensions[k].label);
    const summary=`Trong ngữ cảnh <strong>${relation.label.toLowerCase()}</strong>, hai hồ sơ nổi bật kiểu <strong>“${pattern.title}”</strong>. Vùng đến tự nhiên hơn là <strong>${strengths[0].label.toLowerCase()}</strong>; vùng nên chủ động nói rõ hơn là <strong>${challenges[0].label.toLowerCase()}</strong>. Với ngữ cảnh này, ba trục nên ưu tiên đọc là <strong>${focusNames.join(' → ')}</strong>.`;

    const voiceA=this.profileVoice(A),voiceB=this.profileVoice(B);
    const story={
      title:`${A.profile.fullName} ↔ ${B.profile.fullName}: ${pattern.title}`,
      body:`<strong>${A.profile.fullName}</strong> đi vào quan hệ với trục <b>${voiceA.title}</b>, còn <strong>${B.profile.fullName}</strong> mang trục <b>${voiceB.title}</b>. ${pattern.text} Khi đọc báo cáo, hãy ưu tiên xem điều này có khớp với cách hai người thật sự giao tiếp trong 3–6 tháng gần đây hay không.`
    };

    const adviceMap={
      'Giá trị & hướng sống':'Mỗi người viết ra 3 ưu tiên dài hạn quan trọng nhất rồi so phần giao nhau và phần cần thương lượng. Đừng dùng câu “chúng ta chắc hiểu nhau” thay cho việc nói cụ thể.',
      'Nhu cầu cảm xúc':'Mỗi người hoàn thành câu: “Khi căng thẳng, điều giúp tôi nhất là…”. Nói rõ cần lắng nghe, cần không gian hay cần giải pháp.',
      'Giao tiếp & biểu đạt':'Thống nhất một quy tắc bất đồng: nói vấn đề cụ thể, không gắn nhãn con người; nếu cần tạm dừng thì phải hẹn thời điểm quay lại.',
      'Phát triển & bổ trợ':'Phân vai theo thế mạnh nhưng giữ trách nhiệm cá nhân. Bổ trợ không có nghĩa một người phải làm hộ phần trưởng thành của người kia.',
      'Nhịp hiện tại':'Nếu đang khác nhịp, thống nhất một mốc ngắn 1–3 tháng thay vì ép cả hai có cùng tốc độ ngay lập tức.'
    };
    const practicalAdvice=[...new Set(challenges.map(x=>adviceMap[x.label]))].filter(Boolean);
    while(practicalAdvice.length<3)practicalAdvice.push('Đối chiếu mọi nhận định với hành vi thực tế: giữ lời, xin lỗi, tôn trọng ranh giới và cách giải quyết vấn đề quan trọng hơn điểm số mô hình.');

    const completenessParts=[profileA.birthTime,profileB.birthTime,profileA.gender,profileB.gender].filter(Boolean).length;
    const completeness=70+completenessParts*7.5;
    const missing=[];
    if(!profileA.birthTime||!profileB.birthTime)missing.push('giờ sinh của một hoặc cả hai người');
    if(!profileA.gender||!profileB.gender)missing.push('giới tính dùng cho lớp Cung phi của một hoặc cả hai người');

    const expertSections=[
      {kicker:'1. BẢN CHẤT CẶP ĐÔI',title:pattern.title,body:`${pattern.text} Điểm đồng điệu nền tảng của bốn trục chính là <strong>${naturalFit}/100</strong>, nhưng con số này chỉ dùng để nhìn tương quan nội bộ. Điều quan trọng hơn là vùng mạnh nhất <strong>${strengths[0].label}</strong> có đang xuất hiện thành hành vi tốt ngoài đời thực hay không.`},
      {kicker:'2. ĐIỂM DỄ HIỂU LẦM',title:`Tập trung vào ${challenges[0].label.toLowerCase()}`,body:`Trục này đang ở mức <strong>${challenges[0].score}/100</strong>. ${challenges[0].short}. Điểm thấp không phải bằng chứng thiếu tình cảm hay thiếu thiện chí; nó chỉ cho thấy hai người nên bỏ cách đoán ý và chuyển sang quy ước cụ thể.`},
      {kicker:'3. NGỮ CẢNH HIỆN TẠI',title:`${relation.label} • ${dimensions.current.score}/100 nhịp hiện tại`,body:`Năm cá nhân ${A.values.personalYear} ↔ ${B.values.personalYear} cho thấy ${dimensions.current.short.toLowerCase()}. Nhịp này có thể thay đổi theo năm, vì vậy không nên biến một giai đoạn đang khó thành nhãn cố định về toàn bộ mối quan hệ.`}
    ];

    const realityChecklist=[
      'Hai người có thể nói “không” hoặc đặt ranh giới mà không bị trừng phạt, đe dọa hay kiểm soát không?',
      'Khi có lỗi, người gây ảnh hưởng có nhận trách nhiệm và thay đổi hành vi hay chỉ xin lỗi bằng lời?',
      'Những chủ đề lớn như tiền bạc, gia đình, sự nghiệp, cam kết và riêng tư có thể được nói thẳng mà không phải né tránh kéo dài không?',
      'Mối quan hệ có giúp mỗi người giữ được bản sắc, quyền tự quyết và cảm giác an toàn trong thời gian dài không?'
    ];

    const conversationPrompts=this.contextPrompts(type,challenges,A,B);

    return {
      type,relationLabel:relation.label,overall,label,summary,A,B,dimensions,branch,element,kua,zodiac,
      strengths,challenges,expertSections,practicalAdvice,realityChecklist,conversationPrompts,
      naturalFit,effortIndex,effort,pattern,spreadLabel,story,
      dataCompleteness:this.clamp(completeness),missing,
      disclaimer:'Toàn bộ điểm và mô tả trong phần Độ hợp là mô hình tham khảo/phản tư được tạo từ các quy tắc nội bộ của ứng dụng. Đây không phải xác suất thành công, không phải chẩn đoán tâm lý và không thể biết một người có trung thực, tử tế hay sẵn sàng thay đổi hành vi hay không. Mọi quyết định vẫn cần dựa vào chính hai người: hành vi thực tế, giá trị sống, giao tiếp, tôn trọng, ranh giới, hoàn cảnh và trách nhiệm với lựa chọn của mình.'
    };
  }
}


/* ===== models/date-scorer.js ===== */

/** Transparent reference scorer. Pure model, no DOM. */
class DateScorer{
  static elementRelation(dayEl,userEl){if(dayEl===userEl)return {score:6,label:`Đồng hành ${dayEl}`,detail:`Can ngày và Can năm sinh cùng hành ${dayEl}`};if(MysticalData.GENERATES[dayEl]===userEl)return {score:10,label:'Ngày sinh trợ tuổi',detail:`${dayEl} sinh ${userEl}: cộng điểm hỗ trợ`};if(MysticalData.GENERATES[userEl]===dayEl)return {score:3,label:'Tuổi sinh cho ngày',detail:`${userEl} sinh ${dayEl}: thuận nhưng hao lực hơn`};if(MysticalData.CONTROLS[dayEl]===userEl)return {score:-10,label:'Ngày khắc tuổi',detail:`${dayEl} khắc ${userEl}: trừ điểm`};if(MysticalData.CONTROLS[userEl]===dayEl)return {score:-4,label:'Tuổi khắc ngày',detail:`${userEl} khắc ${dayEl}: có độ ma sát`};return {score:0,label:'Ngũ hành trung tính',detail:'Không có quan hệ sinh/khắc trực tiếp trong mô hình'}}
  static weekday(date,purpose){const d=date.getDay();if(['work','contract','study'].includes(purpose)){if(d>=1&&d<=5)return {score:5,label:'Tính thực tiễn ngày làm việc',detail:'Ngày trong tuần thuận hơn cho cơ quan, ký kết hoặc học tập'};return {score:-3,label:'Tính thực tiễn cuối tuần',detail:'Cuối tuần có thể hạn chế lịch cơ quan/dịch vụ'}}if(purpose==='travel'){if(d===0||d===6)return {score:4,label:'Nhịp cuối tuần',detail:'Cộng nhẹ cho mục đích đi lại/du lịch'};return {score:1,label:'Ngày thường',detail:'Không có ưu/nhược điểm lớn theo lịch làm việc'}}return {score:0,label:'Thứ trong tuần',detail:'Không áp dụng hệ số thực tiễn đáng kể'}}
  static purposeElement(el,purpose){const preferred={general:['Thổ','Mộc'],work:['Hỏa','Kim'],contract:['Kim','Thổ'],travel:['Thủy','Mộc'],love:['Mộc','Hỏa'],study:['Mộc','Thủy']};if((preferred[purpose]||[]).includes(el))return {score:6,label:`Can ngày ${el} hợp mục đích`,detail:`Mô hình ưu tiên ${preferred[purpose].join('/')} cho ${MysticalData.PURPOSE_NAME[purpose]}`};return {score:0,label:`Can ngày ${el}`,detail:'Không thuộc nhóm hành ưu tiên của mục đích'}}
  static personalDay(profile,date,purpose){const n=NumerologyCalculator.personalDay(profile.birthDate,date),map={general:[1,6,8],work:[1,4,8],contract:[2,4,8],travel:[3,5,9],love:[2,3,6],study:[4,7,9]};if((map[purpose]||[]).includes(n))return {score:5,label:`Ngày cá nhân ${n}`,detail:`Số ${n} được cộng nhẹ cho ${MysticalData.PURPOSE_NAME[purpose]}`};return {score:0,label:`Ngày cá nhân ${n}`,detail:'Không có hệ số cộng/trừ cho mục đích đã chọn'}}
  static branchRelation(userBranch,dayBranch){
    const rel=AstrologyCalculator.relations(userBranch);
    if(rel.trine.includes(dayBranch))return {score:18,label:'Tam hợp Địa Chi',detail:`Ngày ${MysticalData.BRANCHES[dayBranch]} nằm trong Tam hợp với tuổi ${MysticalData.BRANCHES[userBranch]}`};
    if(MysticalData.SIX_HARMONY[userBranch]===dayBranch)return {score:12,label:'Lục hợp Địa Chi',detail:`${MysticalData.BRANCHES[userBranch]} ↔ ${MysticalData.BRANCHES[dayBranch]} là cặp Lục hợp trực tiếp`};
    if(dayBranch===rel.clash)return {score:-28,label:'Lục xung / Đối xung',detail:`Ngày ${MysticalData.BRANCHES[dayBranch]} đối xung trực tiếp tuổi ${MysticalData.BRANCHES[userBranch]}`};
    if(dayBranch===userBranch)return {score:5,label:'Đồng Chi',detail:`Ngày và tuổi cùng Chi ${MysticalData.BRANCHES[userBranch]}`};
    const four=AstrologyCalculator.fourClashInfo(userBranch);
    if(four?.members.includes(dayBranch))return {score:-8,label:'Cùng nhóm Tứ hành xung',detail:`${MysticalData.BRANCHES[userBranch]} và ${MysticalData.BRANCHES[dayBranch]} cùng nhóm ${four.name}, nhưng không phải cặp đối xung trực tiếp`};
    return {score:0,label:'Quan hệ Địa Chi trung tính',detail:`${MysticalData.BRANCHES[dayBranch]} không Tam hợp, Lục hợp hoặc Lục xung trực tiếp với ${MysticalData.BRANCHES[userBranch]}`};
  }
  static score(profile,date,purpose){
    const by=AstrologyCalculator.yearCanChi(new Date(profile.birthDate+'T12:00:00').getFullYear()),dc=AstrologyCalculator.dayCanChi(date),factors=[];
    let score=56;
    factors.push(this.branchRelation(by.branchIndex,dc.branchIndex),this.elementRelation(dc.element,by.element),this.purposeElement(dc.element,purpose),this.weekday(date,purpose),this.personalDay(profile,date,purpose));
    factors.forEach(f=>score+=f.score);score=Math.max(12,Math.min(96,score));
    const positives=factors.filter(f=>f.score>0).sort((a,b)=>b.score-a.score),negatives=factors.filter(f=>f.score<0).sort((a,b)=>a.score-b.score);
    return {date,score,dc,lunar:LunarConverter.fromDate(date),factors,positives,negatives};
  }
  static range(profile,purpose,from,to){
    const diff=Math.round((to-from)/86400000);if(diff<0)throw new Error('Đến ngày phải sau hoặc bằng từ ngày.');if(diff>60)throw new Error('Khoảng phân tích tối đa 60 ngày.');
    const list=[];for(let i=0;i<=diff;i++)list.push(this.score(profile,Format.addDays(from,i),purpose));
    list.sort((a,b)=>b.score-a.score||b.positives.length-a.positives.length||a.date-b.date);
    const best=list[0],good=list.filter(x=>x.score>=68).length,by=AstrologyCalculator.yearCanChi(new Date(profile.birthDate+'T12:00:00').getFullYear()),top3=list.slice(0,3);
    const distribution={excellent:list.filter(x=>x.score>=80).length,good:list.filter(x=>x.score>=68&&x.score<80).length,neutral:list.filter(x=>x.score>=52&&x.score<68).length,low:list.filter(x=>x.score<52).length};
    const gap=list.length>1?best.score-list[1].score:best.score;
    const separation=gap>=10?'Tách biệt rõ':gap>=5?'Có ưu thế':gap>=2?'Khá sát nhau':'Gần như ngang điểm';
    const bestReason={positive:best.positives[0]||null,caution:best.negatives[0]||null};
    const scores=list.map(x=>x.score),average=Math.round(scores.reduce((a,b)=>a+b,0)/scores.length),sorted=[...scores].sort((a,b)=>a-b),median=sorted.length%2?sorted[(sorted.length-1)/2]:Math.round((sorted[sorted.length/2-1]+sorted[sorted.length/2])/2),spread=Math.max(...scores)-Math.min(...scores),nearTop=list.filter(x=>best.score-x.score<=3).length;
    const robustness=nearTop===1&&gap>=5?'Ngày #1 có ưu thế tương đối rõ':nearTop<=2?'Có một phương án cạnh tranh sát':'Nhiều ngày gần như tương đương';
    const purposeFocus={general:'ưu tiên sự cân bằng tổng thể và khả năng triển khai thực tế',work:'ưu tiên nhịp làm việc, yếu tố hành phù hợp và ngày thuận tiện cho cơ quan/đối tác',contract:'ưu tiên sự ổn định, tính thực tiễn ngày làm việc và giảm các quan hệ xung mạnh',travel:'ưu tiên tính linh hoạt, nhịp di chuyển và yếu tố thực tế của lịch trình',love:'ưu tiên nhịp mềm, khả năng kết nối và tránh đặt điểm số cao hơn sự đồng thuận thực tế',study:'ưu tiên tính tập trung, lịch học/thi thực tế và nhịp cá nhân phù hợp'}[purpose]||'ưu tiên sự cân bằng tổng thể';
    const expertAnalysis=`<div class="expert-report compact-expert"><section class="expert-section expert-lead"><span class="expert-kicker">KẾT LUẬN ĐIỀU HÀNH</span><h4>${separation} · ${best.score}/100</h4><p>Ngày <strong>${Format.vn(best.date,{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric'})}</strong> đang đứng đầu. ${robustness}. Điểm #1 cao hơn #2 <strong>${gap} điểm</strong>; có <strong>${nearTop}</strong> ngày nằm trong biên 3 điểm so với vị trí dẫn đầu. Vì vậy, ${nearTop>2?'không nên tuyệt đối hóa thứ hạng; hãy dùng lịch thực tế để chọn giữa nhóm đầu.':'có thể ưu tiên ngày đứng đầu nếu điều kiện thực tế cũng phù hợp.'}</p></section><section class="expert-section"><span class="expert-kicker">1. CƠ SỞ XẾP HẠNG</span><h4>${bestReason.positive?bestReason.positive.label:'Không có điểm cộng vượt trội'}</h4><p>${bestReason.positive?`Yếu tố hỗ trợ mạnh nhất đóng góp <strong>+${bestReason.positive.score}</strong>: ${bestReason.positive.detail}.`:'Ngày đứng đầu chủ yếu nhờ tổng hợp nhiều yếu tố nhỏ.'} ${bestReason.caution?`Yếu tố cần cân nhắc lớn nhất là <strong>${bestReason.caution.label} (${bestReason.caution.score})</strong>: ${bestReason.caution.detail}.`:'Không có yếu tố trừ điểm trong mô hình cho ngày này.'}</p></section><section class="expert-section"><span class="expert-kicker">2. ĐỘ ỔN ĐỊNH CỦA KẾT QUẢ</span><h4>Trung bình ${average} · Trung vị ${median} · Biên độ ${spread} điểm</h4><p>Những thống kê này cho biết bảng xếp hạng phân tán đến đâu. Biên độ lớn nghĩa là khoảng ngày có sự khác biệt rõ hơn theo mô hình; biên độ nhỏ nghĩa là nhiều ngày gần nhau và các yếu tố thực tế như lịch cơ quan, sức khỏe, người tham gia hoặc thời tiết nên được ưu tiên hơn.</p></section><section class="expert-section"><span class="expert-kicker">3. THEO MỤC ĐÍCH</span><h4>${MysticalData.PURPOSE_NAME[purpose]}</h4><p>Với mục đích này, mô hình ${purposeFocus}. Điểm số chỉ là <strong>công cụ sắp thứ tự tham khảo</strong>, không phải xác suất thành công. Nếu một ngày điểm cao nhưng xung đột lịch, pháp lý, sức khỏe hoặc điều kiện thực tế, hãy ưu tiên điều kiện thực tế.</p></section></div>`;
    return {purpose,list,best,good,by,top3,distribution,gap,separation,bestReason,average,median,spread,nearTop,robustness,expertAnalysis};
  }
  static rank(s){return s>=80?['Rất phù hợp','excellent']:s>=68?['Khá phù hợp','good']:s>=52?['Trung tính','neutral']:['Nên cân nhắc','low']}
}


