const FeatureConfig={
  tarot:{accent:'amethyst',icon:'#i-tarot',title:'Tarot'},
  fortune:{accent:'emerald',icon:'#i-number',title:'Thần số học'},
  horoscope:{accent:'gold',icon:'#i-horoscope',title:'Tử vi'},
  compatibility:{accent:'rose',icon:'#i-compatibility',title:'Độ hợp'},
  dates:{accent:'blue',icon:'#i-calendar',title:'Xem ngày'}
};

